import { NativeEventEmitter, NativeModules } from 'react-native';

/**
 * Audio device types supported by the AudioMode module
 */
export type AudioDevice = 'BLUETOOTH' | 'EARPIECE' | 'HEADPHONES' | 'SPEAKER';

/**
 * Audio modes supported by the AudioMode module
 */
export enum AudioMode {
  /** Default mode used before and after calls */
  DEFAULT = 0,
  /** Audio-only calls mode (uses earpiece by default) */
  AUDIO_CALL = 1,
  /** Video calls mode (uses speaker by default) */
  VIDEO_CALL = 2,
}

/**
 * Device information structure returned in device change events
 */
export interface AudioDeviceInfo {
  type: AudioDevice;
  selected: boolean;
}

interface AudioModeModuleInterface {
  /**
   * Audio mode constants
   */
  readonly DEFAULT: number;
  readonly AUDIO_CALL: number;
  readonly VIDEO_CALL: number;
  readonly DEVICE_CHANGE_EVENT: string;

  /**
   * Add a listener for React Native events (required for RN built-in Event Emitter)
   * @param eventName - The name of the event to listen for
   */
  addListener: (eventName: string) => void;

  /**
   * Remove listeners for React Native events (required for RN built-in Event Emitter)
   * @param count - The number of listeners to remove
   */
  removeListeners: (count: number) => void;

  /**
   * Sets the user selected audio device as the active audio device
   * @param device - The desired audio device to activate
   */
  setAudioDevice: (device: AudioDevice) => void;

  /**
   * Sets the current audio mode
   * @param mode - The desired audio mode (DEFAULT, AUDIO_CALL, or VIDEO_CALL)
   * @returns Promise that resolves if successful, rejects with error message if failed
   */
  setMode: (mode: AudioMode | number) => Promise<void>;

  /**
   * Sets whether ConnectionService should be used for audio mode management
   * @param use - Boolean indicating whether to use ConnectionService
   */
  setUseConnectionService: (use: boolean) => void;

  /**
   * Updates the list of available audio devices
   */
  updateDeviceList: () => void;
}

const AudioModeModule: AudioModeModuleInterface = NativeModules.AudioMode;

/**
 * Event emitter for AudioMode module events
 */
export const AudioModeEventEmitter = new NativeEventEmitter(AudioModeModule);

export default AudioModeModule;
