import {
  EVENT_LISTENER_METHODS_MOBILE as EVENT_LISTENER_METHODS,
  eventBus,
  MobileSDKEvents,
} from '@cometchat/calls-sdk-core';
import { NativeModules } from 'react-native';

const CometChatEvent: MobileSDKEvents = new Proxy(
  NativeModules.CometChatEvent ?? {},
  {
    get: (
      target: Partial<MobileSDKEvents>,
      property: keyof MobileSDKEvents,
    ) => {
      if (typeof target[property] === 'function') {
        return target[property];
      }
      return () => {
        // console.error(
        //   `CometChatEvent.${property} is not a function or does not exist.`,
        // );
      };
    },
  },
);

