import {
  GRID_GAP,
  useAllParticipants,
  useBaseStore,
  useMainParticipant,
} from '@cometchat/calls-sdk-core';
import React from 'react';
import { StyleSheet, View } from 'react-native';
import Tile from '../tile/Tile.native';
import GroupAvatarTile from './GroupAvatarTile.native';

const useSidebarTileLayout = () => {
  let participantsCount = useAllParticipants().length;
  const mainAreaDimension = useBaseStore(state => state.mainAreaDimension);

  return React.useMemo(() => {
    if (participantsCount > 1) {
      // This is to avoid 2 participants view in sidebar layout
      participantsCount++;
    }
    let tileWidthFirst = mainAreaDimension.width;
    let tileHeightFirst = mainAreaDimension.height;
    let tileWidthOther = 0;
    let tileHeightOther = 0;
    let numberOfRows = 1;
    let numberOfCols = 1;
    if (participantsCount === 2) {
      tileWidthOther = mainAreaDimension.width;
      tileHeightOther = tileWidthOther * (9 / 16);
      tileHeightFirst = mainAreaDimension.height - GRID_GAP - tileHeightOther;
    } else if (participantsCount === 3) {
      tileWidthOther = (mainAreaDimension.width - GRID_GAP) / 2;
      tileHeightOther = tileWidthOther * (3 / 4);
      tileHeightFirst = mainAreaDimension.height - GRID_GAP - tileHeightOther;
      numberOfCols = 2;
    } else if (participantsCount === 4) {
      tileWidthOther = (mainAreaDimension.width - GRID_GAP * 2) / 3;
      tileHeightOther = tileWidthOther;
      tileHeightFirst = mainAreaDimension.height - GRID_GAP - tileHeightOther;
      numberOfCols = 3;
    } else if (participantsCount >= 5) {
      tileWidthOther = (mainAreaDimension.width - GRID_GAP) / 2;
      tileHeightOther = tileWidthOther * (3 / 4);
      tileHeightFirst =
        mainAreaDimension.height - GRID_GAP * 2 - tileHeightOther * 2;
      numberOfRows = 2;
      numberOfCols = 2;
    }
    return {
      tileWidthFirst,
      tileHeightFirst,
      tileWidthOther,
      tileHeightOther,
      numberOfRows,
      numberOfCols,
    };
  }, [participantsCount, mainAreaDimension.width, mainAreaDimension.height]);
};

function SidebarLayout(): React.JSX.Element {
  const allParticipants = useAllParticipants();
  const participantsLayout = useSidebarTileLayout();
  const mainParticipant = useMainParticipant();

  const participants =
    allParticipants.length > 1
      ? [mainParticipant].concat(allParticipants)
      : [mainParticipant];

  return (
    <View testID="cometchat-sidebar-layout" style={styles.container}>
      <Tile
        participant={participants[0]}
        style={{
          width: participantsLayout.tileWidthFirst,
          height: participantsLayout.tileHeightFirst,
        }}
      />
      {participantsLayout.numberOfRows >= 1 && (
        <View style={styles.row}>
          {participants
            .slice(1, 1 + participantsLayout.numberOfCols)
            .map(participant => (
              <Tile
                key={participant.ruid}
                participant={participant}
                style={{
                  width: participantsLayout.tileWidthOther,
                  height: participantsLayout.tileHeightOther,
                }}
              />
            ))}
        </View>
      )}
      {participantsLayout.numberOfRows >= 2 && (
        <View style={styles.row}>
          <Tile
            key={participants[3].ruid}
            participant={participants[3]}
            style={{
              width: participantsLayout.tileWidthOther,
              height: participantsLayout.tileHeightOther,
            }}
          />
          {participants.length === 5 && (
            <Tile
              key={participants[4].ruid}
              participant={participants[4]}
              style={{
                width: participantsLayout.tileWidthOther,
                height: participantsLayout.tileHeightOther,
              }}
            />
          )}
          {participants.length > 5 && (
            <GroupAvatarTile
              startIndex={3}
              style={{
                width: participantsLayout.tileWidthOther,
                height: participantsLayout.tileHeightOther,
              }}
            />
          )}
        </View>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    gap: GRID_GAP,
  },
  row: {
    flexDirection: 'row',
    justifyContent: 'center',
    gap: GRID_GAP,
  },
});

export default SidebarLayout;
