import {
  toggleParticipantListVisible,
  useOrderedParticipants,
} from '@cometchat/calls-sdk-core';
import React, { useState } from 'react';
import {
  FlatList,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from 'react-native';
import Icon from '../icon/Icon.native';
import ShareInviteButton from '../shared/ShareInviteButton.native';
import { colors, commonStyles } from '../theme/style-variables';
import ParticipantItem from './participant-item/ParticipantItem.native'; // Adjusted import path

const ListEmptyComponent = () => (
  <Text style={[commonStyles.heading3Bold, styles.noResults]}>
    No participants found.
  </Text>
);

const ParticipantList: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const participants = useOrderedParticipants();

  const filteredParticipants = participants.filter(p =>
    p.name.toLowerCase().includes(searchTerm.toLowerCase()),
  );

  return (
    <View style={styles.participantListContainer}>
      {/* Header */}
      <View style={styles.participantListHeader}>
        <Text style={[commonStyles.heading2Bold, styles.headerTitle]}>
          Participants ({filteredParticipants.length})
        </Text>
        <TouchableOpacity
          onPress={toggleParticipantListVisible}
          accessibilityLabel="Close participants list"
          testID="cometchat-participant-list-close-button">
          <Icon name="close" size={24} fill="#FFFFFF" />
        </TouchableOpacity>
      </View>

      <ShareInviteButton />

      {/* Search Bar */}
      <View style={styles.searchContainer}>
        <View style={styles.searchInputWrapper}>
          <Icon name="search" size={24} fill="#858585" />
          <TextInput
            placeholder="Search Participant"
            style={styles.searchInput}
            value={searchTerm}
            onChangeText={setSearchTerm} // Use onChangeText for TextInput
            placeholderTextColor="#858585"
            testID="cometchat-participant-search-input"
          />
        </View>
      </View>

      {/* Participant List Area */}
      <FlatList
        data={filteredParticipants}
        renderItem={({ item }) => <ParticipantItem participant={item} />}
        keyExtractor={item => item.ruid}
        ListEmptyComponent={ListEmptyComponent}
      />
    </View>
  );
};

const styles = StyleSheet.create({
  participantListContainer: {
    flex: 1,
    backgroundColor: '#1A1A1A',
  },
  participantListHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: 16,
    gap: 12,
    borderBottomWidth: 1,
    borderBottomColor: '#383838',
  },
  headerTitle: {
    color: '#ffffff',
  },
  searchContainer: {
    flexDirection: 'row',
    alignItems: 'flex-start',
    paddingVertical: 12,
    paddingHorizontal: 16,
  },
  searchInputWrapper: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 12,
    gap: 8,
    height: 40,
    backgroundColor: '#272727',
    borderWidth: 1,
    borderColor: '#272727',
    borderRadius: 1000,
    flex: 1,
  },
  searchInput: {
    ...commonStyles.heading4Regular,
    flex: 1,
    color: '#ffffff',
  },
  noResults: {
    padding: 20,
    textAlign: 'center',
    width: '100%',
    color: colors.text.primary,
  },
});

export default ParticipantList;
