import {
  CAMERA_FACING,
  CAMERA_FACING_INTERNAL,
  LAYOUT,
  MEDIA_TYPE,
  PARTICIPANT_ROLE,
  SDK_PLATFORM,
  SESSION_TYPE,
} from '../utils';

type AudioModeType = 'BLUETOOTH' | 'EARPIECE' | 'HEADPHONES' | 'SPEAKER';

export type AudioMode = {
  type: AudioModeType;
  selected: boolean;
  uid?: string;
};

export type CameraFacingInternal = ValueOf<typeof CAMERA_FACING_INTERNAL>;

export type CameraFacing = ValueOf<typeof CAMERA_FACING>;

export type SessionType = ValueOf<typeof SESSION_TYPE>;

export type Layout = ValueOf<typeof LAYOUT>;

export type MediaType = ValueOf<typeof MEDIA_TYPE>;

export type ValueOf<T> = T[keyof T];

export type ParticipantRole = ValueOf<typeof PARTICIPANT_ROLE>;

export type NotificationType = 'info' | 'success' | 'warning' | 'error';

export type SDKPlatform = ValueOf<typeof SDK_PLATFORM>;

export interface ITrackOptions {
  cameraDeviceId?: string | null;
  constraints?: {
    video?: {
      height?: {
        ideal?: number;
        max?: number;
        min?: number;
      };
    };
  };
  desktopSharingSourceDevice?: string;
  desktopSharingSources?: string[];
  devices?: string[];
  facingMode?: string;
  firePermissionPromptIsShownEvent?: boolean;
  micDeviceId?: string | null;
  timeout?: number;
}

export type Prettify<T> = {
  [K in keyof T]: T[K];
} & unknown;

// Utility type to extract all dot-notation paths
export type Paths<T> = T extends object
  ? {
      [K in keyof T]: T[K] extends object
        ? `${K & string}.${Paths<T[K]>}`
        : `${K & string}`;
    }[keyof T]
  : never;
