import {
  EVENT_LISTENER_METHODS,
  eventBus,
  MEDIA_TYPE,
  toggleVideoTrack,
  useHideToggleVideoButton,
  useTrackMuted,
} from '@cometchat/calls-sdk-core';
import React from 'react';
import { TouchableOpacity } from 'react-native';
import Icon from '../../icon/Icon.native'; // Assuming this is RN compatible
import { controlPaneStyles } from '../styles.native';

const VideoControl: React.FC = () => {
  const hidePauseVideoButton = useHideToggleVideoButton();
  const videoMuted = useTrackMuted(MEDIA_TYPE.VIDEO);

  if (hidePauseVideoButton) {
    return null;
  }

  const onPress = () => {
    eventBus.publish({
      type: EVENT_LISTENER_METHODS.ButtonClickListener
        .onToggleVideoButtonClicked,
    });
    toggleVideoTrack();
  };

  return (
    <TouchableOpacity
      style={[
        controlPaneStyles.controlButton,
        videoMuted && controlPaneStyles.toggledButton,
      ]}
      onPress={onPress}
      activeOpacity={0.7}
      testID="cometchat-video-toggle-button">
      <Icon
        name={videoMuted ? 'video-off-fill' : 'video-fill'}
        fill={videoMuted ? '#9F3032' : '#FFF'}
        size={24}
      />
    </TouchableOpacity>
  );
};

export default VideoControl;
