import { useBaseStore } from '@cometchat/calls-sdk-core';
import React, { useRef } from 'react';
import {
  Animated,
  Modal,
  Pressable,
  StyleSheet,
  Text,
  TouchableOpacity,
} from 'react-native';
import Icon from '../icon/Icon.native';
import { IconName } from '../icon/icon-paths-24x24';
import { commonStyles } from '../theme/style-variables';

const POPUP_MENU_WIDTH = 180;
const DISABLED_OPTION_OPACITY = 0.5;

export const PopupMenu = ({
  visible,
  onClose,
  options,
  anchorLayout,
}: {
  visible: boolean;
  onClose: () => void;
  options: {
    label: string;
    onPress: () => void;
    iconName?: IconName;
    selected?: boolean;
  }[];
  anchorLayout: { x: number; y: number; width: number; height: number };
}) => {
  const scaleAnim = useRef(new Animated.Value(0.7)).current;
  const callContainerDimension = useBaseStore(
    state => state.callContainerDimension,
  );

  React.useEffect(() => {
    if (visible) {
      Animated.spring(scaleAnim, {
        toValue: 1,
        useNativeDriver: true,
        friction: 12,
        tension: 200,
      }).start();
    } else {
      scaleAnim.setValue(0.7);
    }
  }, [scaleAnim, visible]);

  if (!visible || !anchorLayout) {
    return null;
  }

  const { x, y, height } = anchorLayout;
  const minLeft = callContainerDimension.width - POPUP_MENU_WIDTH - 10;
  const isBelowMiddle = callContainerDimension.height >> 1 < y;

  return (
    <Modal
      transparent
      animationType="none"
      supportedOrientations={['portrait', 'landscape-left', 'landscape-right']}
      onRequestClose={onClose}>
      <Pressable
        style={styles.backdrop}
        onPress={onClose}
        testID="cometchat-popup-menu-backdrop"
        accessible={false}>
        <Animated.View
          style={[
            styles.menu,
            {
              [isBelowMiddle ? 'bottom' : 'top']: isBelowMiddle
                ? callContainerDimension.height - (y - 4)
                : y + height + 4,
              left: Math.min(minLeft, x),
              transform: [
                { scale: scaleAnim },
                {
                  translateY: scaleAnim.interpolate({
                    inputRange: [0.7, 1],
                    outputRange: [-40, 0],
                  }),
                },
              ],
            },
          ]}>
          {options.map((option, index) => (
            <TouchableOpacity
              key={index}
              onPress={e => {
                if (option.selected) {
                  e.stopPropagation();
                  return;
                }
                option.onPress();
                onClose();
              }}
              activeOpacity={option.selected ? DISABLED_OPTION_OPACITY : 0.2}
              style={[
                styles.menuItem,
                option.selected ? styles.menuItemSelected : {},
              ]}
              testID={`cometchat-popup-menu-option-${index}`}
              accessible={true}
              accessibilityLabel={option.label}>
              {option.iconName && (
                <Icon name={option.iconName} size={24} fill="#858585" />
              )}
              <Text style={[commonStyles.bodyRegular, styles.menuText]}>
                {option.label}
              </Text>
            </TouchableOpacity>
          ))}
        </Animated.View>
      </Pressable>
    </Modal>
  );
};

const styles = StyleSheet.create({
  backdrop: {
    flex: 1,
  },
  menu: {
    position: 'absolute',
    backgroundColor: '#141414',
    borderWidth: 1,
    borderColor: '#383838',
    borderRadius: 16,
    paddingVertical: 8,
    width: POPUP_MENU_WIDTH,
    shadowColor: '#000',
    shadowOpacity: 0.3,
    shadowRadius: 8,
    shadowOffset: { width: 0, height: 4 },
    elevation: 8,
    overflow: 'hidden',
  },
  menuItem: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingVertical: 8,
    paddingHorizontal: 16,
    height: 40,
    gap: 8,
  },
  menuItemSelected: {
    opacity: DISABLED_OPTION_OPACITY,
  },
  menuText: {
    color: '#FFFFFF',
    flex: 1,
  },
  iconPlaceholder: {
    width: 24,
    height: 24,
    backgroundColor: '#858585',
    borderRadius: 4,
  },
});

export default PopupMenu;
