import React, { useCallback, useEffect, useRef } from 'react';
import {
  Animated,
  Dimensions,
  ScrollView,
  StyleSheet,
  TouchableWithoutFeedback,
  View,
} from 'react-native';
import { commonStyles } from '../theme/style-variables';

const SCREEN_HEIGHT = Dimensions.get('window').height;

interface BottomSheetProps {
  children: React.ReactNode;
  isVisible: boolean;
  onClose: () => void;
  maxHeight?: number;
  testID?: string;
}

const BottomSheet: React.FC<BottomSheetProps> = ({
  children,
  isVisible,
  onClose,
  maxHeight = SCREEN_HEIGHT * 0.4,
  testID,
}) => {
  const visibleTranslateY = SCREEN_HEIGHT - maxHeight;

  const hiddenTranslateY = useRef(SCREEN_HEIGHT).current;
  const animatedValue = useRef(new Animated.Value(hiddenTranslateY)).current;

  const springAnimation = useCallback(
    (direction: 'up' | 'down') => {
      const toValue = direction === 'up' ? visibleTranslateY : hiddenTranslateY;
      Animated.spring(animatedValue, {
        toValue,
        useNativeDriver: true,
        bounciness: 0,
      }).start();
    },
    [animatedValue, hiddenTranslateY, visibleTranslateY],
  );

  useEffect(() => {
    if (isVisible) {
      springAnimation('up');
    } else {
      springAnimation('down');
    }
  }, [isVisible, springAnimation]);

  const bottomSheetAnimation = {
    transform: [
      {
        translateY: animatedValue,
      },
    ],
  };

  // Conditionally render the backdrop and sheet to allow animation even when isVisible becomes false
  // The component itself will be controlled by its parent for complete unmounting if needed.
  return (
    <>
      {isVisible && (
        <TouchableWithoutFeedback
          onPress={onClose}
          testID="cometchat-bottom-sheet-backdrop">
          <View style={[commonStyles.absoluteFill, styles.backdrop]} />
        </TouchableWithoutFeedback>
      )}
      <Animated.View
        testID={testID}
        style={[
          styles.bottomSheet,
          bottomSheetAnimation,
          { height: maxHeight },
        ]}>
        <View style={styles.draggableArea}>
          <View style={styles.dragHandle} />
        </View>
        <ScrollView>{children}</ScrollView>
      </Animated.View>
    </>
  );
};

const styles = StyleSheet.create({
  backdrop: {
    backgroundColor: 'rgba(0,0,0,0.5)',
    zIndex: 1,
  },
  bottomSheet: {
    position: 'absolute',
    width: '100%',
    backgroundColor: '#1A1A1A',
    borderTopLeftRadius: 16,
    borderTopRightRadius: 16,
    paddingBottom: 8,
    borderWidth: 1,
    borderColor: '#383838',
    zIndex: 2,
    // bottom: 0, // Not needed as translateY handles positioning from the top
    left: 0,
    right: 0,
    top: 0, // Initial top position, translateY will move it down
    // Shadow for iOS
    shadowColor: '#101828',
    shadowOffset: {
      width: 0,
      height: -6,
    },
    shadowOpacity: 0.08,
    shadowRadius: 10,
    // Elevation for Android
    elevation: 8,
  },
  draggableArea: {
    width: '100%',
    alignItems: 'center',
    paddingVertical: 10,
    borderTopLeftRadius: 20,
    borderTopRightRadius: 20,
  },
  dragHandle: {
    width: 32,
    height: 4,
    backgroundColor: '#A1A1A1',
    borderRadius: 1000,
  },
});

export default BottomSheet;
