import {
  eventBus,
  getIsConferenceJoined,
  INTERNAL_EVENTS,
  pauseVideoTrack,
  resumeVideoTrack,
  SESSION_TYPE,
  useBaseStore,
  useConfigStore,
  VIDEO_PAUSE_AUTHORITY,
} from '@cometchat/calls-sdk-core';
import { AppState } from 'react-native';

eventBus.subscribe(INTERNAL_EVENTS.lifecycle.componentDidMount, () => {
  AppState.addEventListener('change', appState => {
    useBaseStore.setState({
      appState: appState,
    });
  });
});

useBaseStore.subscribe(
  state => state.appState,
  async appState => {
    if (!getIsConferenceJoined()) {
      return;
    }
    const sessionType = useConfigStore.getState().sessionType;
    if (sessionType !== SESSION_TYPE.VIDEO) {
      return;
    }
    if (appState === 'active') {
      resumeVideoTrack(VIDEO_PAUSE_AUTHORITY.BACKGROUND);
    } else {
      // TODO: Find a better way to handle the race condition between app state change and PIP mode change
      await new Promise(resolve => setTimeout(resolve, 2000));
      if (useBaseStore.getState().isPIPLayoutEnabled) {
        return;
      }
      pauseVideoTrack(VIDEO_PAUSE_AUTHORITY.BACKGROUND);
    }
  },
);
