import { ConfigState, eventBus } from '@cometchat/calls-sdk-core';
import React, { useEffect } from 'react';
import './native-communication/js-to-native';
import './native-communication/native-to-js.native';
import CallUI from './ui/index.native';
import InfoView from './ui/InfoView.native';

function App(props: Partial<ConfigState>) {
  const [isConnectionClosed, setIsConnectionClosed] = React.useState(false);

  useEffect(() => {
    return eventBus.subscribe('onConnectionClosed', () => {
      setTimeout(() => {
        setIsConnectionClosed(true);
      }, 0);
    });
  }, []);

  if (isConnectionClosed) {
    return <InfoView text="The session has ended." />;
  }

  return <CallUI sessionSettings={props} />;
}

export default App;
