import {
  Participant,
  useAllParticipants,
  useBaseStore,
  useConfigStore,
  useMainParticipant,
} from '@cometchat/calls-sdk-core';
import React from 'react';
import { StyleSheet, View } from 'react-native';
import { Pan } from '../pan/Pan.native';
import Tile from '../tile/Tile.native';

export const Spotlight = () => {
  const mainParticipant = useMainParticipant();
  const allParticipants = useAllParticipants();
  const mainAreaDimension = useBaseStore(state => state.mainAreaDimension);
  const enableSpotlightDrag = useConfigStore(
    state => state.enableSpotlightDrag,
  );
  const enableSpotlightSwap = useConfigStore(
    state => state.enableSpotlightSwap,
  );

  const spotlightParticipants: Participant[] = [mainParticipant];
  const otherParticipant = allParticipants.find(
    participant => participant.ruid !== mainParticipant.ruid,
  );
  if (otherParticipant) {
    spotlightParticipants.push(otherParticipant);
  }

  return (
    <View testID="cometchat-spotlight-layout">
      <Tile
        key={spotlightParticipants[0].ruid}
        participant={spotlightParticipants[0]}
        disablePress={true}
      />
      {spotlightParticipants[1] && (
        <Pan
          disableDrag={!enableSpotlightDrag}
          layout={{
            width: mainAreaDimension.width,
            height: mainAreaDimension.height,
          }}>
          <Tile
            key={spotlightParticipants[1].ruid}
            showLabel={false}
            disablePress={!enableSpotlightSwap}
            participant={spotlightParticipants[1]}
            style={styles.panTile}
            zOrder={1}
          />
        </Pan>
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  panTile: {
    borderColor: '#1A1A1A',
    borderWidth: 2,
  },
});
