import React from 'react';
import Svg, { Path } from 'react-native-svg';
import { IconName, PATH_MAP } from './icon-paths-24x24';

type IconProps = {
  name: IconName;
  size?: number;
  fill?: string;
};

const Icon: React.FC<IconProps> = ({ name, size = 24, fill }) => {
  const paths =
    typeof PATH_MAP[name] === 'string' ? [PATH_MAP[name]] : PATH_MAP[name];
  return (
    <Svg width={size} height={size} viewBox="0 0 24 24" fill="none">
      {paths.map((path, index) => (
        <Path key={index} d={path} fill={fill} />
      ))}
    </Svg>
  );
};

export default Icon;
