import {
  ConfigStateBoth,
  ConfigStateInternal,
  ConfigStateMobile,
  eventBus,
  INTERNAL_EVENTS,
  SESSION_TYPE,
  startSession,
  toggleAudioModeMenuVisible,
  toggleMoreMenuVisible,
  updateConfig,
  useBaseStore,
  useConfigStore,
  useIsConferenceJoined,
} from '@cometchat/calls-sdk-core';
import React, { useEffect, useLayoutEffect } from 'react';
import { Platform, StyleSheet, View } from 'react-native';
import AudioModeModule, {
  AudioModeEventEmitter,
} from '../native-communication/AudioModeModule';
import '../native-only';
import CallStage from './CallStage.native';
import { ConfirmationDialog } from './confirmation-dialog/ConfirmationDialog';
import AudioModesMenu from './control-pane/AudioModesMenu.native';
import ControlPane from './control-pane/ControlPane.native';
import MoreMenu from './control-pane/MoreMenu.native';
import FullScreenDialog from './full-screen-dialog/FullScreenDialog.native';
import Header from './header/Header.native';
import IdealTimeoutModal from './ideal-timeout/IdealTimeoutModal.native';
import ParticipantList from './participants/ParticipantList.native';
import PiPTile from './PiPTile';
import { ProcessingOverlay } from './processing-overlay/ProcessingOverlay.native';
import { Toast } from './toast/Toast.native';

interface CallUIProps {
  sessionSettings: Partial<
    ConfigStateInternal & ConfigStateMobile & ConfigStateBoth
  >;
}

function CallUI(props: CallUIProps): React.JSX.Element {
  const moreMenuVisible = useBaseStore(state => state.moreMenuVisible);
  const participantListVisible = useBaseStore(
    state => state.participantListVisible,
  );
  const isPIPLayoutEnabled = useBaseStore(state => state.isPIPLayoutEnabled);
  const audioModeMenuVisible = useBaseStore(
    state => state.audioModeMenuVisible,
  );
  const type = useConfigStore(state => state.sessionType);
  const isConferenceJoined = useIsConferenceJoined();

  useLayoutEffect(() => {
    eventBus.publish({
      type: INTERNAL_EVENTS.lifecycle.componentDidMount,
    });
    updateConfig(props.sessionSettings);
    return () => {
      eventBus.publish(
        {
          type: INTERNAL_EVENTS.lifecycle.componentWillUnmount,
        },
        true,
      );
    };
  }, [props.sessionSettings]);

  useEffect(() => {
    if (props.sessionSettings.sdkPlatform) {
      useBaseStore.setState({
        sdkPlatform: props.sessionSettings.sdkPlatform,
      });
    } else {
      useBaseStore.setState({
        sdkPlatform:
          Platform.OS === 'ios' ? 'react-native-ios' : 'react-native-android',
      });
    }
    useBaseStore.setState({
      platformVersion: Platform.Version,
    });
    startSession();
  }, [props.sessionSettings.sdkPlatform]);

  useEffect(() => {
    const sub = AudioModeEventEmitter.addListener(
      AudioModeModule.DEVICE_CHANGE_EVENT,
      e => {
        useBaseStore.setState({
          audioModes: e,
        });
      },
    );

    return () => {
      sub.remove();
    };
  }, []);

  useEffect(() => {
    if (Platform.OS === 'android') {
      AudioModeModule.setMode(
        type === SESSION_TYPE.VOICE
          ? AudioModeModule.AUDIO_CALL
          : AudioModeModule.VIDEO_CALL,
      );
      if (props.sessionSettings.audioMode) {
        AudioModeModule.setAudioDevice(props.sessionSettings.audioMode);
      }
    } else if (Platform.OS === 'ios') {
      AudioModeModule.updateDeviceList();
    }
  }, [props.sessionSettings.audioMode, type]);

  if (isPIPLayoutEnabled) {
    return <PiPTile />;
  }

  return (
    <View
      style={styles.container}
      onLayout={e => {
        useBaseStore.setState({
          callContainerDimension: {
            width: e.nativeEvent.layout.width,
            height: e.nativeEvent.layout.height,
          },
        });
      }}>
      <Header />
      <CallStage />
      <ControlPane />
      <FullScreenDialog visible={participantListVisible}>
        <ParticipantList />
      </FullScreenDialog>
      <MoreMenu isVisible={moreMenuVisible} onClose={toggleMoreMenuVisible} />
      <AudioModesMenu
        isVisible={audioModeMenuVisible}
        onClose={toggleAudioModeMenuVisible}
      />
      <IdealTimeoutModal />
      <ProcessingOverlay
        message="Connecting..."
        visible={!isConferenceJoined}
      />
      <ConfirmationDialog />
      <Toast />
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#1A1A1A',
  },
});

export default CallUI;
