import {
  EVENT_LISTENER_METHODS,
  eventBus,
  MEDIA_TYPE,
  toggleAudioTrack,
  useHideMuteAudioButton,
  useTrackMuted,
} from '@cometchat/calls-sdk-core';
import React from 'react';
import { TouchableOpacity } from 'react-native';
import Icon from '../../icon/Icon.native'; // Assuming this is RN compatible
import { controlPaneStyles } from '../styles.native';

const AudioControl: React.FC = () => {
  const muted = useTrackMuted(MEDIA_TYPE.AUDIO);
  const hideMuteAudioButton = useHideMuteAudioButton();

  if (hideMuteAudioButton) {
    return null;
  }

  const onPress = () => {
    eventBus.publish({
      type: EVENT_LISTENER_METHODS.ButtonClickListener
        .onToggleAudioButtonClicked,
    });
    toggleAudioTrack();
  };

  return (
    <TouchableOpacity
      style={[
        controlPaneStyles.controlButton,
        muted && controlPaneStyles.toggledButton,
      ]}
      onPress={onPress}
      activeOpacity={0.7}
      testID="cometchat-audio-toggle-button">
      <Icon
        name={muted ? 'mic-off-fill' : 'mic-fill'}
        fill={muted ? '#9F3032' : '#FFF'}
        size={24}
      />
    </TouchableOpacity>
  );
};

export default AudioControl;
