import { create } from 'zustand';
import type { NotificationType } from '../types/common';
import { getIsConferenceJoined } from './conference';
import { useConfigStore } from './config';

const MAX_TOASTS = 3;

export interface ToastAction {
  label: string;
  onPress: () => void;
}

export interface ToastItem {
  id: string;
  message: string;
  type: NotificationType;
  duration: number;
  position: 'top' | 'bottom';
  action?: ToastAction;
  createdAt: number;
}

interface ToastState {
  toasts: ToastItem[];
}

interface ToastActions {
  addToast: (toast: Omit<ToastItem, 'id' | 'createdAt'>) => string;
  removeToast: (id: string) => void;
  clearAll: () => void;
  reset: () => void;
}

const initialState: ToastState = {
  toasts: [],
};

let counter = 0;

export const useToastStore = create<ToastState & ToastActions>(set => ({
  ...initialState,

  addToast: toast => {
    if (!getIsConferenceJoined()) {
      return '';
    }

    if (!useConfigStore.getState().enableNotifications) {
      return '';
    }

    const id = `toast-${++counter}-${Date.now()}`;
    const newToast: ToastItem = {
      ...toast,
      id,
      createdAt: Date.now(),
    };

    set(state => {
      const updated = [...state.toasts, newToast];
      // Keep only the latest MAX_TOASTS
      if (updated.length > MAX_TOASTS) {
        return { toasts: updated.slice(-MAX_TOASTS) };
      }
      return { toasts: updated };
    });

    return id;
  },

  removeToast: id => {
    set(state => ({
      toasts: state.toasts.filter(t => t.id !== id),
    }));
  },

  clearAll: () => {
    set(initialState);
  },

  reset: () => {
    set(initialState);
  },
}));

export function showToast(params: {
  message: string;
  type?: NotificationType;
  duration?: number;
  position?: 'top' | 'bottom';
  action?: ToastAction;
}): string {
  return useToastStore.getState().addToast({
    message: params.message,
    type: params.type ?? 'info',
    duration: params.duration ?? 3000,
    position: params.position ?? 'bottom',
    action: params.action,
  });
}
