import { eventBus, useConfigStore } from '@cometchat/calls-sdk-core';
import React from 'react';
import { StyleSheet, Text, TouchableOpacity, View } from 'react-native';
import Icon from '../icon/Icon.native';
import { commonStyles } from '../theme/style-variables';

const ShareInviteButton = () => {
  const hideShareInviteButton = useConfigStore(
    state => state.hideShareInviteButton,
  );

  if (hideShareInviteButton) {
    return null;
  }

  return (
    <View style={styles.shareButtonContainer}>
      <TouchableOpacity
        style={styles.shareButton}
        testID="cometchat-share-invite-button"
        onPress={() => {
          eventBus.publish({
            type: 'onShareInviteButtonClicked',
          });
        }}>
        <Icon name="share" size={24} fill="#FFFFFF" />
        <Text style={[commonStyles.heading4Medium, styles.shareButtonText]}>
          Share Invite
        </Text>
      </TouchableOpacity>
    </View>
  );
};

const styles = StyleSheet.create({
  shareButtonContainer: {
    paddingHorizontal: 16,
    paddingVertical: 12,
  },
  shareButton: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: '#8C78F0',
    borderRadius: 8,
    paddingVertical: 12,
    paddingHorizontal: 16,
    gap: 8,
  },
  shareButtonText: {
    color: '#FFFFFF',
  },
});

export default ShareInviteButton;
