import {
  toggleAudioModeMenuVisible,
  useConfigStore,
} from '@cometchat/calls-sdk-core';
import React from 'react';
import { TouchableOpacity } from 'react-native';
import Icon from '../icon/Icon.native';
import { controlPaneStyles } from './styles.native';

const AudioModeButton: React.FC = () => {
  const hideAudioModeButton = useConfigStore(
    state => state.hideAudioModeButton,
  );

  if (hideAudioModeButton) {
    return null;
  }

  return (
    <TouchableOpacity
      style={controlPaneStyles.controlButton}
      onPress={toggleAudioModeMenuVisible}
      activeOpacity={0.7}
      testID="cometchat-audio-mode-button">
      <Icon name="speaker-fill" fill="#FFF" size={24} />
    </TouchableOpacity>
  );
};

export default AudioModeButton;
