import {
  EVENT_LISTENER_METHODS,
  eventBus,
  toggleParticipantListVisible,
  toggleRaiseHand,
  toggleRecording,
  useConfigStore,
  useHideRecordingButton,
  useHideScreenSharingButton,
  useIsRecording,
  useRaisedHandTimestamp,
  useTranslation,
} from '@cometchat/calls-sdk-core';
import React, { useCallback } from 'react';
import { ScrollView, StyleSheet, Text } from 'react-native';
import BottomSheet from '../bottom-sheet/BottomSheet.native';
import { showConfirmationDialog } from '../confirmation-dialog/confirmation-dialog-state';
import { commonStyles } from '../theme/style-variables';
import MenuItem from './MenuItem.native';
import ScreenShareButton from './ScreenShareButton';

interface MoreMenuProps {
  isVisible: boolean;
  onClose: () => void;
}

const MoreMenu: React.FC<MoreMenuProps> = ({ isVisible, onClose }) => {
  const raiseHandTimestamp = useRaisedHandTimestamp();
  const hideRecordingButton = useHideRecordingButton();
  const { t } = useTranslation();

  const isRecording = useIsRecording();

  const hideRaiseHandButton = useConfigStore(
    state => state.hideRaiseHandButton,
  );

  const hideParticipantListButton = useConfigStore(
    state => state.hideParticipantListButton,
  );

  const hideScreenSharingButton = useHideScreenSharingButton();

  let numberOfVisibleItems = 0;
  if (hideRecordingButton === false) {
    numberOfVisibleItems++;
  }
  if (hideRaiseHandButton === false) {
    numberOfVisibleItems++;
  }
  if (hideParticipantListButton === false) {
    numberOfVisibleItems++;
  }
  if (hideScreenSharingButton === false) {
    numberOfVisibleItems++;
  }
  const bottomSheetMaxHeight = 124 + Math.max(numberOfVisibleItems, 1) * 48;

  const onRaiseHandPress = useCallback(() => {
    eventBus.publish({
      type: EVENT_LISTENER_METHODS.ButtonClickListener.onRaiseHandButtonClicked,
    });
    toggleRaiseHand();
  }, []);

  const onParticipantListPress = useCallback(() => {
    eventBus.publish({
      type: EVENT_LISTENER_METHODS.ButtonClickListener
        .onParticipantListButtonClicked,
    });
    toggleParticipantListVisible();
  }, []);

  return (
    <BottomSheet
      testID="cometchat-more-menu-bottom-sheet"
      maxHeight={bottomSheetMaxHeight}
      isVisible={isVisible}
      onClose={onClose}>
      <ScrollView>
        {numberOfVisibleItems === 0 && (
          <Text
            testID="cometchat-more-menu-empty-state"
            style={[commonStyles.bodyRegular, styles.noItemsText]}>
            No options available
          </Text>
        )}
        {!hideScreenSharingButton && <ScreenShareButton />}
        {!hideRaiseHandButton && (
          <MenuItem
            testID="cometchat-menu-item-raise-hand"
            iconName="raise-hand-fill"
            label={raiseHandTimestamp ? 'Lower Hand' : 'Raise Hand'}
            onPress={onRaiseHandPress}
            selected={Boolean(raiseHandTimestamp)}
          />
        )}
        {!hideRecordingButton && (
          <MenuItem
            testID={
              isRecording
                ? 'cometchat-menu-item-stop-recording'
                : 'cometchat-menu-item-start-recording'
            }
            iconName={isRecording ? 'record-stop-fill' : 'record-fill'}
            label={isRecording ? 'Stop Recording' : 'Start Recording'}
            onPress={() => {
              eventBus.publish({
                type: EVENT_LISTENER_METHODS.ButtonClickListener
                  .onRecordingToggleButtonClicked,
              });
              showConfirmationDialog(
                isRecording
                  ? t('controlPanel.recording.stopRecording')
                  : t('controlPanel.recording.startRecording'),
                isRecording
                  ? t('controlPanel.recording.stopRecordingConfirmation')
                  : t('controlPanel.recording.startRecordingConfirmation'),
                isRecording
                  ? t('controlPanel.recording.stopRecording')
                  : t('controlPanel.recording.startRecording'),
                t('controlPanel.recording.cancel'),
                () => {
                  toggleRecording();
                },
              );
            }}
          />
        )}
        {!hideParticipantListButton && (
          <MenuItem
            testID="cometchat-menu-item-participants"
            iconName="participants"
            label="Participants"
            onPress={onParticipantListPress}
          />
        )}
      </ScrollView>
    </BottomSheet>
  );
};

const styles = StyleSheet.create({
  noItemsText: {
    padding: 16,
    textAlign: 'center',
    color: '#888',
  },
});

export default MoreMenu;
