import {
  EVENT_LISTENER_METHODS_MOBILE,
  eventBus,
  useBaseStore,
  useHideChatButton,
} from '@cometchat/calls-sdk-core';
import React, { useCallback } from 'react';
import { StyleSheet, Text, TouchableOpacity, View } from 'react-native';
import Icon from '../icon/Icon.native';
import {
  borderRadius,
  colors,
  commonStyles,
  padding,
} from '../theme/style-variables';

const ChatButton = () => {
  const hideChatButton = useHideChatButton();
  const chatButtonUnreadCount = useBaseStore(
    state => state.chatButtonUnreadCount,
  );

  const onPress = useCallback(() => {
    eventBus.publish({
      type: EVENT_LISTENER_METHODS_MOBILE.ButtonClickListener
        .onChatButtonClicked,
    });
  }, []);

  if (hideChatButton) {
    return null;
  }

  return (
    <TouchableOpacity
      style={[styles.iconButton]}
      onPress={onPress}
      testID="cometchat-chat-button">
      <Icon name="chat" fill={'#FFFFFF'} />
      {chatButtonUnreadCount > 0 && (
        <View style={styles.badge}>
          <Text style={styles.badgeText}>
            {chatButtonUnreadCount > 99 ? '99+' : chatButtonUnreadCount}
          </Text>
        </View>
      )}
    </TouchableOpacity>
  );
};

const styles = StyleSheet.create({
  iconButton: {
    justifyContent: 'center',
    alignItems: 'center',
    width: 40,
    height: 40,
    backgroundColor: '#272727',
    borderRadius: 1000,
    flexShrink: 0,
  },
  badge: {
    position: 'absolute',
    top: -1,
    right: -1,
    backgroundColor: colors.primary,
    borderRadius: borderRadius.max,
    minWidth: 18,
    height: 18,
    justifyContent: 'center',
    alignItems: 'center',
    paddingHorizontal: padding[1],
  },
  badgeText: {
    color: colors.static.white,
    textAlign: 'center',
    ...commonStyles.caption1Bold,
  },
});

export default ChatButton;
