import { hideAllBottomSheets } from '@cometchat/calls-sdk-core';
import React from 'react';
import { StyleSheet, Text, TouchableOpacity } from 'react-native';
import Icon from '../icon/Icon.native';
import { IconName } from '../icon/icon-paths-24x24';
import { colors, commonStyles } from '../theme/style-variables';

interface MenuItemProps {
  iconName: IconName;
  label: string;
  onPress: () => void;
  selected?: boolean;
  testID?: string;
}

const MenuItem: React.FC<MenuItemProps> = ({
  iconName,
  label,
  onPress,
  selected = false,
  testID,
}) => {
  return (
    <TouchableOpacity
      testID={testID}
      onPress={() => {
        hideAllBottomSheets();
        onPress();
      }}
      style={[styles.menuItem, selected && styles.menuItemSelected]}>
      <Icon name={iconName} size={24} fill="#858585" />
      <Text style={[commonStyles.heading4Regular, styles.menuLabel]}>
        {label}
      </Text>
    </TouchableOpacity>
  );
};

const styles = StyleSheet.create({
  menuItem: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 16,
    paddingVertical: 12,
    gap: 8,
  },
  menuItemSelected: {
    backgroundColor: '#383838',
  },
  menuLabel: {
    color: colors.text.primary,
    textTransform: 'capitalize',
  },
});

export default MenuItem;
