import {
  eventBus,
  INTERNAL_EVENTS,
  type ToastItem,
  useToastStore,
} from '@cometchat/calls-sdk-core';
import React, { useCallback, useEffect, useRef } from 'react';
import { Animated, Pressable, Text, View } from 'react-native';
import { styles } from './styles';

const SLIDE_IN_DURATION = 300;
const SLIDE_OUT_DURATION = 200;

const typeStyleMap = {
  info: styles.toastInfo,
  success: styles.toastSuccess,
  warning: styles.toastWarning,
  error: styles.toastError,
} as const;

function ToastItemView({
  toast,
  onDismiss,
}: {
  toast: ToastItem;
  onDismiss: (id: string) => void;
}) {
  const opacity = useRef(new Animated.Value(0)).current;
  const translateY = useRef(
    new Animated.Value(toast.position === 'top' ? -20 : 20),
  ).current;
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const dismiss = useCallback(() => {
    Animated.parallel([
      Animated.timing(opacity, {
        toValue: 0,
        duration: SLIDE_OUT_DURATION,
        useNativeDriver: true,
      }),
      Animated.timing(translateY, {
        toValue: toast.position === 'top' ? -20 : 20,
        duration: SLIDE_OUT_DURATION,
        useNativeDriver: true,
      }),
    ]).start(() => {
      onDismiss(toast.id);
    });
  }, [onDismiss, opacity, toast.id, toast.position, translateY]);

  useEffect(() => {
    // Slide in
    Animated.parallel([
      Animated.timing(opacity, {
        toValue: 1,
        duration: SLIDE_IN_DURATION,
        useNativeDriver: true,
      }),
      Animated.timing(translateY, {
        toValue: 0,
        duration: SLIDE_IN_DURATION,
        useNativeDriver: true,
      }),
    ]).start();

    // Auto-dismiss
    timerRef.current = setTimeout(dismiss, toast.duration);

    return () => {
      if (timerRef.current) {
        clearTimeout(timerRef.current);
      }
    };
  }, [dismiss, opacity, toast.duration, translateY]);

  const handleActionPress = () => {
    toast.action?.onPress();
    dismiss();
  };

  return (
    <Animated.View
      style={[
        styles.toast,
        typeStyleMap[toast.type],
        { opacity, transform: [{ translateY }] },
      ]}>
      <Text style={styles.message}>{toast.message}</Text>
      {toast.action && (
        <Pressable
          style={styles.actionButton}
          onPress={handleActionPress}
          testID="cometchat-toast-action-button">
          <Text style={styles.actionText}>{toast.action.label}</Text>
        </Pressable>
      )}
    </Animated.View>
  );
}

export function Toast() {
  const toasts = useToastStore(state => state.toasts);
  const removeToast = useToastStore(state => state.removeToast);

  useEffect(() => {
    const unsubscribe = eventBus.subscribe(
      INTERNAL_EVENTS.notification,
      payload => {
        useToastStore.getState().addToast({
          message: payload.message,
          type: payload.type,
          duration: payload.duration ?? 3000,
          position: payload.position ?? 'bottom',
          action: payload.action,
        });
      },
    );

    return unsubscribe;
  }, []);

  const topToasts = toasts.filter(t => t.position === 'top');
  const bottomToasts = toasts.filter(t => t.position === 'bottom');

  return (
    <>
      {topToasts.length > 0 && (
        <View style={styles.containerTop} pointerEvents="box-none">
          {topToasts.map(toast => (
            <ToastItemView
              key={toast.id}
              toast={toast}
              onDismiss={removeToast}
            />
          ))}
        </View>
      )}
      {bottomToasts.length > 0 && (
        <View style={styles.containerBottom} pointerEvents="box-none">
          {bottomToasts.map(toast => (
            <ToastItemView
              key={toast.id}
              toast={toast}
              onDismiss={removeToast}
            />
          ))}
        </View>
      )}
    </>
  );
}
