import {
  GRID_GAP,
  useAllParticipants,
  useBaseStore,
  useMainParticipant,
} from '@cometchat/calls-sdk-core';
import React from 'react';
import { FlatList, StyleSheet } from 'react-native';
import Tile from '../tile/Tile.native';

export const getTileDimensions = ({
  layout,
  participantCount,
}: {
  layout: { width: number; height: number };
  participantCount: number;
}) => {
  if (participantCount < 4) {
    return {
      tileWidth: layout.width,
      tileHeight:
        (layout.height - GRID_GAP * (participantCount - 1)) / participantCount,
    };
  }
  const tileWidth = layout.width / 2;
  const tileHeight = Math.max(
    layout.height / Math.ceil(participantCount / 2),
    (tileWidth * 9) / 16,
  );

  return {
    tileWidth,
    tileHeight,
  };
};

function TileLayout(): React.JSX.Element {
  const participants = useAllParticipants();
  const isPIPLayoutEnabled = useBaseStore(state => state.isPIPLayoutEnabled);
  const mainParticipant = useMainParticipant();
  const mainArea = useBaseStore(state => state.mainAreaDimension);

  const tileLayout = getTileDimensions({
    layout: mainArea,
    participantCount: isPIPLayoutEnabled ? 1 : participants.length,
  });

  return (
    <FlatList
      testID="cometchat-tile-layout"
      data={isPIPLayoutEnabled ? [mainParticipant] : participants}
      renderItem={({ item }) => (
        <Tile
          participant={item}
          style={{
            width: tileLayout.tileWidth,
            height: tileLayout.tileHeight,
          }}
        />
      )}
      keyExtractor={item => item.ruid}
      contentContainerStyle={styles.contentContainerStyle}
      showsVerticalScrollIndicator={false}
      onViewableItemsChanged={e => {
        if (e.viewableItems.length === 0) {
          return;
        }
      }}
      showsHorizontalScrollIndicator={false}
      horizontal={false}
      key={participants.length < 4 ? 1 : 2}
      numColumns={participants.length < 4 ? 1 : 2}
      {...(participants.length < 4
        ? {}
        : { columnWrapperStyle: { gap: GRID_GAP } })}
    />
  );
}

const styles = StyleSheet.create({
  contentContainerStyle: {
    alignItems: 'center',
    gap: GRID_GAP,
    paddingHorizontal: 20,
  },
});

export default TileLayout;
