import { useBaseStore } from '@cometchat/calls-sdk-core';
import React from 'react';
import { NativeModules, ScrollView, StyleSheet, Text } from 'react-native';
import BottomSheet from '../bottom-sheet/BottomSheet.native';
import { colors, commonStyles } from '../theme/style-variables';
import MenuItem from './MenuItem.native';
const { AudioMode } = NativeModules;

interface AudioModesMenuProps {
  isVisible: boolean;
  onClose: () => void;
}

const AUDIO_MODE_TYPE_ICON_MAP = {
  BLUETOOTH: 'bluetooth',
  CAR: 'car',
  EARPIECE: 'earpiece',
  HEADPHONES: 'headphones',
  SPEAKER: 'speaker-fill',
} as const;

const AudioModesMenu: React.FC<AudioModesMenuProps> = ({
  isVisible,
  onClose,
}) => {
  const audioModes = useBaseStore(state => state.audioModes);

  const bottomSheetMaxHeight = 124 + Math.max(audioModes.length, 1) * 48;

  return (
    <BottomSheet
      maxHeight={bottomSheetMaxHeight}
      isVisible={isVisible}
      onClose={onClose}>
      <ScrollView>
        {audioModes.length === 0 && (
          <Text style={[commonStyles.bodyRegular, styles.noItemsText]}>
            No audio modes available
          </Text>
        )}
        {audioModes.map((mode, index) => (
          <MenuItem
            key={index}
            testID={`cometchat-menu-item-audio-${mode.type.toLowerCase()}`}
            iconName={AUDIO_MODE_TYPE_ICON_MAP[mode.type]}
            label={mode.type}
            selected={mode.selected}
            onPress={() => {
              AudioMode.setAudioDevice(mode.uid || mode.type);
            }}
          />
        ))}
      </ScrollView>
    </BottomSheet>
  );
};

const styles = StyleSheet.create({
  noItemsText: {
    padding: 16,
    textAlign: 'center',
    color: colors.text.secondary,
  },
});

export default AudioModesMenu;
