import React, { useEffect, useRef } from 'react';
import { Animated, PanResponder, StyleSheet } from 'react-native';

interface IPan {
  layout: { width: number; height: number };
  children: React.ReactNode;
  margin?: number;
  disableDrag?: boolean;
}

export const Pan: React.FC<IPan> = ({
  layout,
  children,
  margin = 8,
  disableDrag = false,
}) => {
  const BOX_WIDTH = layout.width / 4;
  const BOX_HEIGHT = layout.height / 4;
  const pan = useRef(
    new Animated.ValueXY({
      x: layout.width - BOX_WIDTH - margin,
      y: layout.height - BOX_HEIGHT - margin,
    }),
  ).current;
  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onMoveShouldSetPanResponder: () => true,
      onPanResponderGrant: () => {
        pan.extractOffset(); // Save current value to offset, reset value to 0
      },
      onPanResponderMove: Animated.event([null, { dx: pan.x, dy: pan.y }], {
        useNativeDriver: false,
      }),
      onPanResponderRelease: () => {
        pan.flattenOffset();
      },
    }),
  ).current;

  useEffect(() => {
    pan.setValue({
      x: layout.width - BOX_WIDTH - margin,
      y: layout.height - BOX_HEIGHT - margin,
    });
  }, [layout, pan, BOX_WIDTH, BOX_HEIGHT, margin]);

  if (
    layout.width < BOX_WIDTH + margin * 2 ||
    layout.height < BOX_HEIGHT + margin * 2
  ) {
    return null;
  }
  return (
    <Animated.View
      {...(disableDrag ? {} : panResponder.panHandlers)}
      style={[
        styles.box,
        {
          width: BOX_WIDTH,
          height: BOX_HEIGHT,
        },
        {
          transform: [
            {
              translateX: pan.x.interpolate({
                inputRange: [margin, layout.width - BOX_WIDTH - margin],
                outputRange: [margin, layout.width - BOX_WIDTH - margin],
                extrapolate: 'clamp',
              }),
            },
            {
              translateY: pan.y.interpolate({
                inputRange: [margin, layout.height - BOX_HEIGHT - margin],
                outputRange: [margin, layout.height - BOX_HEIGHT - margin],
                extrapolate: 'clamp',
              }),
            },
          ],
        },
      ]}>
      {children}
    </Animated.View>
  );
};

const styles = StyleSheet.create({
  box: {
    position: 'absolute',
    borderRadius: 10,
    overflow: 'hidden',
  },
});
