import {
  EVENT_LISTENER_METHODS,
  eventBus,
  leaveSession,
  useConfigStore,
} from '@cometchat/calls-sdk-core';
import React from 'react';
import { TouchableOpacity } from 'react-native';
import Icon from '../icon/Icon.native'; // Assuming this is RN compatible
import { controlPaneStyles } from './styles.native';

const LeaveSessionButton: React.FC = () => {
  const hideLeaveSessionButton = useConfigStore(
    state => state.hideLeaveSessionButton,
  );

  if (hideLeaveSessionButton) {
    return null;
  }

  const onPress = () => {
    leaveSession();
    eventBus.publish({
      type: EVENT_LISTENER_METHODS.ButtonClickListener
        .onLeaveSessionButtonClicked,
    });
  };

  return (
    <TouchableOpacity
      style={[
        controlPaneStyles.controlButton,
        controlPaneStyles.leaveSessionButton,
      ]}
      onPress={onPress}
      activeOpacity={0.7}
      testID="cometchat-leave-session-button">
      <Icon name="call-end" fill="#FFF" size={24} />
    </TouchableOpacity>
  );
};

export default LeaveSessionButton;
