import React from 'react';
import { Modal, Pressable, Text, TouchableOpacity, View } from 'react-native';
import { useConfirmationDialogStore } from './confirmation-dialog-state';
import { styles } from './styles';
import { commonStyles } from '../theme/style-variables';

export function ConfirmationDialog() {
  const {
    title,
    description,
    cancelText,
    confirmText,
    onCancel,
    onConfirm,
    onBackdropClick,
    visible,
  } = useConfirmationDialogStore();

  const handleBackdropPress = () => {
    if (onBackdropClick) {
      onBackdropClick();
    }
  };

  return (
    <Modal
      visible={visible}
      transparent={true}
      animationType="fade"
      supportedOrientations={['portrait', 'landscape-left', 'landscape-right']}
      onRequestClose={handleBackdropPress}>
      <Pressable
        style={[commonStyles.absoluteFill, styles.backdrop]}
        onPress={handleBackdropPress}
        testID="cometchat-confirmation-dialog-backdrop"
        accessible={false}>
        <View style={styles.dialog}>
          <View style={styles.content}>
            <View style={styles.textContainer}>
              <Text style={styles.title}>{title}</Text>
              <Text style={styles.description}>{description}</Text>
            </View>
            <View style={styles.buttonsContainer}>
              <TouchableOpacity
                style={[styles.button, styles.buttonSecondary]}
                onPress={onCancel}
                testID="cometchat-confirmation-dialog-cancel-button"
                accessible={true}>
                <Text style={[styles.buttonText, styles.buttonTextSecondary]}>
                  {cancelText}
                </Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={[styles.button, styles.buttonPrimary]}
                onPress={onConfirm}
                testID="cometchat-confirmation-dialog-confirm-button"
                accessible={true}>
                <Text style={[styles.buttonText, styles.buttonTextPrimary]}>
                  {confirmText}
                </Text>
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Pressable>
    </Modal>
  );
}
