import {
  miliSecondsToMMSS,
  useConfigStore,
  useSessionTimer,
} from '@cometchat/calls-sdk-core';
import React from 'react';
import { Text, View } from 'react-native';
import { commonStyles } from '../theme/style-variables';
import ChangeLayout from './ChangeLayout';
import ChatButton from './ChatButton';
import { styles } from './styles';
import SwitchCamera from './SwitchCamera';

const SessionTimer = () => {
  const conferenceElapsedTime = useSessionTimer();
  const hideSessionTimer = useConfigStore(state => state.hideSessionTimer);

  if (hideSessionTimer) {
    return null;
  }

  return (
    <Text
      testID="cometchat-session-timer"
      style={[commonStyles.caption1Regular, styles.meetingTime]}>
      {miliSecondsToMMSS(conferenceElapsedTime)}
    </Text>
  );
};

const Header: React.FC = () => {
  const title = useConfigStore(state => state.title);
  const hideHeaderPanel = useConfigStore(state => state.hideHeaderPanel);

  if (hideHeaderPanel) {
    return null;
  }

  return (
    <View style={styles.headerContainer} testID="cometchat-header-panel">
      {/* Left Section: Meeting Info */}
      <View style={styles.meetingInfo}>
        {title && (
          <Text
            testID="cometchat-session-title"
            style={[commonStyles.heading4Medium, styles.meetingTitle]}
            numberOfLines={1}
            ellipsizeMode="tail">
            {title}
          </Text>
        )}
        <SessionTimer />
      </View>

      {/* Right Section: Icon Controls */}
      <View style={styles.iconControls}>
        <SwitchCamera />
        <ChangeLayout />
        <ChatButton />
      </View>
    </View>
  );
};

export default Header;
