import {
  MEDIA_TYPE,
  Participant,
  useRaisedHandTimestamp,
  useTrackMuted,
} from '@cometchat/calls-sdk-core';
import React from 'react';
import { Text, View } from 'react-native';
import Avatar from '../../avatar/Avatar.native';
import Icon from '../../icon/Icon.native';
import { commonStyles } from '../../theme/style-variables';
import ConnectionQualityIndicator from './ConnectionQualityIndicator.native';
import MoreOptionButton from './MoreOptionButton';
import { styles } from './styles';

interface ParticipantItemProps {
  participant: Participant;
}

const ParticipantItem: React.FC<ParticipantItemProps> = ({ participant }) => {
  const { pid, name, avatar, type, ruid } = participant;
  const muted = useTrackMuted(MEDIA_TYPE.AUDIO, participant.pid);

  const description = participant.type === 'screen-share' ? 'Presentation' : '';

  const micIconName = muted ? 'mic-off' : 'mic';
  const micIconColor = muted ? '#858585' : '#6852D6';
  const raisedHandTimestamp = useRaisedHandTimestamp(pid, type);

  return (
    <View style={styles.participantItem}>
      <Avatar
        name={name}
        imageUrl={avatar}
        fontSize={18}
        size={48}
        containerStyle={styles.avatar}
        textStyle={commonStyles.heading3Bold}
      />
      <View style={styles.participantText}>
        <Text
          style={[commonStyles.bodyMedium, styles.participantName]}
          numberOfLines={1}
          ellipsizeMode="tail">
          {name}
        </Text>
        {description && (
          <Text
            style={[
              commonStyles.caption1Regular,
              styles.participantDescription,
            ]}
            numberOfLines={1}
            ellipsizeMode="tail">
            {description}
          </Text>
        )}
      </View>
      <View style={styles.participantIcons}>
        {raisedHandTimestamp ? (
          <Icon name="raise-hand-fill" size={20} fill="#fff" />
        ) : (
          <ConnectionQualityIndicator participantId={pid} />
        )}
        <Icon name={micIconName} size={24} fill={micIconColor} />
        <MoreOptionButton ruid={ruid} />
      </View>
    </View>
  );
};

export default ParticipantItem;
