import {
  EVENT_LISTENER_METHODS_MOBILE,
  eventBus,
  MEDIA_TYPE,
  switchCamera,
  useHideSwitchCameraButton,
  useTrackMuted,
} from '@cometchat/calls-sdk-core';
import React, { useCallback } from 'react';
import { StyleSheet, TouchableOpacity } from 'react-native';
import Icon from '../icon/Icon.native';

const SwitchCamera = () => {
  const videoMuted = useTrackMuted(MEDIA_TYPE.VIDEO);
  const disabled = Boolean(videoMuted);

  const hideSwitchCameraButton = useHideSwitchCameraButton();

  const onPress = useCallback(() => {
    eventBus.publish({
      type: EVENT_LISTENER_METHODS_MOBILE.ButtonClickListener
        .onSwitchCameraButtonClicked,
    });
    switchCamera();
  }, []);

  if (hideSwitchCameraButton) {
    return null;
  }

  return (
    <TouchableOpacity
      testID="cometchat-switch-camera-button"
      disabled={disabled}
      style={[styles.iconButton, disabled && styles.iconButtonDisabled]}
      onPress={onPress}>
      <Icon name="switch-camera" fill={'#FFFFFF'} />
    </TouchableOpacity>
  );
};

const styles = StyleSheet.create({
  iconButton: {
    justifyContent: 'center',
    alignItems: 'center',
    width: 40,
    height: 40,
    backgroundColor: '#272727',
    borderRadius: 1000,
    flexShrink: 0,
  },
  iconButtonDisabled: {
    opacity: 0.5,
  },
});

export default SwitchCamera;
