import React, { useEffect, useRef, useState } from 'react';
import { ActivityIndicator, Animated, StyleSheet, Text } from 'react-native';
import { commonStyles } from '../theme/style-variables';

interface ProcessingOverlayProps {
  message: string;
  visible?: boolean;
  animated?: boolean;
}

export function ProcessingOverlay({
  message,
  visible = true,
  animated = false,
}: ProcessingOverlayProps) {
  const opacity = useRef(new Animated.Value(1)).current;
  const [shouldRender, setShouldRender] = useState(true);

  useEffect(() => {
    if (visible) {
      opacity.setValue(1);
      setShouldRender(true);
    } else {
      if (animated) {
        Animated.timing(opacity, {
          toValue: 0,
          duration: 300,
          useNativeDriver: true,
        }).start(() => {
          // Animation completed, unmount the component
          setShouldRender(false);
        });
      } else {
        setShouldRender(false);
      }
    }
  }, [opacity, visible, animated]);

  // Return null to unmount the component when opacity reaches zero
  if (!shouldRender) {
    return null;
  }

  return (
    <Animated.View
      style={[commonStyles.absoluteFill, styles.overlay, { opacity }]}>
      <ActivityIndicator size="large" color="#fff" />
      <Text style={[commonStyles.bodyRegular, styles.text]}>{message}</Text>
    </Animated.View>
  );
}

const styles = StyleSheet.create({
  overlay: {
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#1A1A1A',

    // This renders below other components in case of Voice call if zIndex is not set or 1
    zIndex: 2,
  },
  text: {
    color: '#fff',
    textAlign: 'center',
    margin: 16,
  },
});
