import { useConfigStore, useIsRecording } from '@cometchat/calls-sdk-core';
import React, { useEffect, useRef } from 'react';
import { Animated, StyleSheet, Text, View } from 'react-native';
import { commonStyles } from '../theme/style-variables';

interface RecordingIndicatorProps {
  style?: any;
}

const RecordingIndicator = ({ style }: RecordingIndicatorProps) => {
  const pulseAnimation = useRef(new Animated.Value(1)).current;
  const isRecording = useIsRecording();
  const hideRecordingStatusIndicator = useConfigStore(
    state => state.hideRecordingStatusIndicator,
  );

  useEffect(() => {
    if (isRecording) {
      const pulse = () => {
        Animated.sequence([
          Animated.timing(pulseAnimation, {
            toValue: 1.1,
            duration: 1000,
            useNativeDriver: true,
          }),
          Animated.timing(pulseAnimation, {
            toValue: 1,
            duration: 1000,
            useNativeDriver: true,
          }),
        ]).start(() => pulse());
      };
      pulse();
    }
  }, [isRecording, pulseAnimation]);

  if (!isRecording || hideRecordingStatusIndicator) {
    return null;
  }

  return (
    <View testID="cometchat-recording-indicator" style={[styles.container, style]}>
      <View style={styles.recordingIndicator}>
        <Animated.View
          style={[
            styles.dot,
            {
              transform: [{ scale: pulseAnimation }],
            },
          ]}
        />
        <Text style={[commonStyles.caption1Bold, styles.text]}>REC</Text>
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    position: 'absolute',
    top: 8,
    left: 8,
  },
  recordingIndicator: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 4,
    paddingVertical: 6,
    paddingHorizontal: 8,
    backgroundColor: 'rgba(255, 255, 255, 0.9)',
    borderRadius: 8,
    borderWidth: 1,
    borderColor: 'rgba(0, 0, 0, 0.1)',
    shadowColor: '#000',
    shadowOffset: {
      width: 0,
      height: 2,
    },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    elevation: 3,
  },
  dot: {
    width: 8,
    height: 8,
    backgroundColor: '#FF3B30',
    borderRadius: 4,
  },
  text: {
    color: '#FF3B30',
    letterSpacing: 0.5,
  },
});

export default RecordingIndicator;
