import {
  GRID_GAP,
  toggleParticipantListVisible,
  useAllParticipants,
} from '@cometchat/calls-sdk-core';
import React from 'react';
import {
  StyleProp,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
  ViewStyle,
} from 'react-native';
import Avatar from '../avatar/Avatar.native';
import { commonStyles } from '../theme/style-variables';

export interface GroupAvatarTileProps {
  startIndex?: number;
  style?: StyleProp<ViewStyle>;
}

const Badge = ({ size = 40, text }: { size: number; text: string }) => {
  return (
    <View
      style={[
        styles.overflowCircle,
        { width: size, height: size, borderRadius: size / 2 },
      ]}>
      <Text style={[commonStyles.heading4Medium, styles.overflowText]}>
        {text}
      </Text>
    </View>
  );
};

const GroupAvatarTile: React.FC<GroupAvatarTileProps> = ({
  startIndex = 4,
  style,
}) => {
  const participants = useAllParticipants();
  const participantCount = participants.length;

  const overflowCount = Math.max(0, participantCount - startIndex - 3);
  const visible = participants.slice(
    startIndex,
    startIndex + (overflowCount === 1 ? 4 : 3),
  );

  return (
    <TouchableOpacity
      testID="cometchat-group-avatar-tile"
      style={[styles.container, style]}
      onPress={toggleParticipantListVisible}>
      {/* first row */}
      <View style={styles.row}>
        {visible.slice(0, 2).map(item => (
          <Avatar
            key={item.ruid}
            size={40}
            name={item.name}
            imageUrl={item.avatar}
          />
        ))}
      </View>

      {/* second row */}
      <View style={styles.row}>
        {visible[2] && (
          <Avatar
            size={40}
            name={visible[2].name}
            imageUrl={visible[2].avatar}
          />
        )}
        {visible[3] ? (
          <Avatar
            size={40}
            name={visible[3].name}
            imageUrl={visible[3].avatar}
          />
        ) : null}

        {/* overflow badge */}
        {overflowCount > 1 && <Badge size={40} text={`+${overflowCount}`} />}
      </View>
    </TouchableOpacity>
  );
};

export default GroupAvatarTile;

const styles = StyleSheet.create({
  container: {
    justifyContent: 'center',
    alignItems: 'center',
    gap: GRID_GAP,
    backgroundColor: '#272727',
    borderRadius: 8,
  },
  row: {
    flexDirection: 'row',
    gap: GRID_GAP,
  },
  overflowCircle: {
    backgroundColor: '#3E3180',
    alignItems: 'center',
    justifyContent: 'center',
  },
  overflowText: {
    color: 'white',
  },
});
