import {
  disablePictureInPictureLayout,
  enablePictureInPictureLayout,
  leaveSession,
  muteAudioTrack,
  muteParticipant,
  pauseParticipantVideo,
  pauseVideoTrack,
  resumeVideoTrack,
  setChatButtonUnreadCount,
  switchCamera,
  unMuteAudioTrack,
  useBaseStore,
} from '@cometchat/calls-sdk-core';
import {
  DeviceEventEmitter,
  EmitterSubscription,
  NativeEventEmitter,
  NativeModules,
  Platform,
} from 'react-native';

const constants = {
  MUTE_AUDIO: 'MUTE_AUDIO',
  UNMUTE_AUDIO: 'UNMUTE_AUDIO',

  PAUSE_VIDEO: 'PAUSE_VIDEO',
  RESUME_VIDEO: 'RESUME_VIDEO',

  ENABLE_PICTURE_IN_PICTURE_LAYOUT: 'ENABLE_PICTURE_IN_PICTURE_LAYOUT',
  DISABLE_PICTURE_IN_PICTURE_LAYOUT: 'DISABLE_PICTURE_IN_PICTURE_LAYOUT',

  LEAVE_SESSION: 'LEAVE_SESSION',

  RAISE_HAND: 'RAISE_HAND',
  LOWER_HAND: 'LOWER_HAND',

  MUTE_PARTICIPANT: 'MUTE_PARTICIPANT',
  PAUSE_PARTICIPANT_VIDEO: 'PAUSE_PARTICIPANT_VIDEO',

  PIN_PARTICIPANT: 'PIN_PARTICIPANT',
  UNPIN_PARTICIPANT: 'UNPIN_PARTICIPANT',

  SET_AUDIO_MODE: 'SET_AUDIO_MODE',
  SET_LAYOUT: 'SET_LAYOUT',
  SWITCH_CAMERA: 'SWITCH_CAMERA',

  START_RECORDING: 'START_RECORDING',
  STOP_RECORDING: 'STOP_RECORDING',

  START_SCREEN_SHARE: 'START_SCREEN_SHARE',
  STOP_SCREEN_SHARE: 'STOP_SCREEN_SHARE',

  SET_CHAT_BUTTON_UNREAD_COUNT: 'SET_CHAT_BUTTON_UNREAD_COUNT',
};

export function setupNativeEventListeners() {
  const { CometChatEventEmitter } = NativeModules;

  const eventEmitter = Platform.select({
    default: CometChatEventEmitter
      ? new NativeEventEmitter(CometChatEventEmitter)
      : null,
    android: DeviceEventEmitter,
  });
  const subscriptions: EmitterSubscription[] = [];

  if (!eventEmitter) {
    return;
  }

  const muteAudioSub = eventEmitter.addListener(constants.MUTE_AUDIO, () => {
    muteAudioTrack();
  });
  subscriptions.push(muteAudioSub);

  const unMuteAudioSub = eventEmitter.addListener(
    constants.UNMUTE_AUDIO,
    () => {
      unMuteAudioTrack();
    },
  );
  subscriptions.push(unMuteAudioSub);

  const pauseVideoSub = eventEmitter.addListener(constants.PAUSE_VIDEO, () => {
    pauseVideoTrack();
  });
  subscriptions.push(pauseVideoSub);

  const resumeVideoSub = eventEmitter.addListener(
    constants.RESUME_VIDEO,
    () => {
      resumeVideoTrack();
    },
  );
  subscriptions.push(resumeVideoSub);

  const enablePiPSub = eventEmitter.addListener(
    constants.ENABLE_PICTURE_IN_PICTURE_LAYOUT,
    () => {
      enablePictureInPictureLayout();
    },
  );
  subscriptions.push(enablePiPSub);

  const disablePiPSub = eventEmitter.addListener(
    constants.DISABLE_PICTURE_IN_PICTURE_LAYOUT,
    () => {
      disablePictureInPictureLayout();
    },
  );
  subscriptions.push(disablePiPSub);

  const leaveSessionSub = eventEmitter.addListener(
    constants.LEAVE_SESSION,
    () => {
      leaveSession();
    },
  );
  subscriptions.push(leaveSessionSub);

  const raiseHandSub = eventEmitter.addListener(constants.RAISE_HAND, () => {});
  subscriptions.push(raiseHandSub);

  const lowerHandSub = eventEmitter.addListener(constants.LOWER_HAND, () => {});
  subscriptions.push(lowerHandSub);

  const muteParticipantSub = eventEmitter.addListener(
    constants.MUTE_PARTICIPANT,
    event => {
      if (typeof event.pid === 'string') {
        muteParticipant(event.pid);
      }
    },
  );
  subscriptions.push(muteParticipantSub);

  const pauseParticipantVideoSub = eventEmitter.addListener(
    constants.PAUSE_PARTICIPANT_VIDEO,
    event => {
      if (typeof event.pid === 'string') {
        pauseParticipantVideo(event.pid);
      }
    },
  );
  subscriptions.push(pauseParticipantVideoSub);

  const pinParticipantSub = eventEmitter.addListener(
    constants.PIN_PARTICIPANT,
    () => {},
  );
  subscriptions.push(pinParticipantSub);

  const unPinParticipantSub = eventEmitter.addListener(
    constants.UNPIN_PARTICIPANT,
    () => {},
  );
  subscriptions.push(unPinParticipantSub);

  const setAudioModeSub = eventEmitter.addListener(
    constants.SET_AUDIO_MODE,
    () => {},
  );
  subscriptions.push(setAudioModeSub);

  const setLayoutSub = eventEmitter.addListener(constants.SET_LAYOUT, () => {});
  subscriptions.push(setLayoutSub);

  const switchCameraSub = eventEmitter.addListener(
    constants.SWITCH_CAMERA,
    () => {
      switchCamera();
    },
  );
  subscriptions.push(switchCameraSub);

  const startRecordingSub = eventEmitter.addListener(
    constants.START_RECORDING,
    () => {},
  );
  subscriptions.push(startRecordingSub);

  const stopRecordingSub = eventEmitter.addListener(
    constants.STOP_RECORDING,
    () => {},
  );
  subscriptions.push(stopRecordingSub);

  const startScreenSharingSub = eventEmitter.addListener(
    constants.START_SCREEN_SHARE,
    () => {},
  );
  subscriptions.push(startScreenSharingSub);

  const stopScreenShareSub = eventEmitter.addListener(
    constants.STOP_SCREEN_SHARE,
    () => {},
  );
  subscriptions.push(stopScreenShareSub);

  eventEmitter.addListener(constants.SET_CHAT_BUTTON_UNREAD_COUNT, event => {
    if (typeof event.count === 'number') {
      setChatButtonUnreadCount(event.count);
    }
  });

  // TODO: Remove subscriptions when the component unmounts or when conference ends or when needed
  useBaseStore.getState().addSubscriptions(subscriptions);
}

// eventBus.subscribe('onSessionJoined', setupNativeEventListeners);
setupNativeEventListeners();
