import { useConfigStore } from '@cometchat/calls-sdk-core';
import React from 'react';
import { View } from 'react-native';
import AudioModeButton from './AudioModeButton';
import AudioControl from './controls/Audio.native';
import VideoControl from './controls/Video.native';
import LeaveSessionButton from './LeaveSessionButton.native';
import MoreMenuButton from './MoreMenuButton';
import { controlPaneStyles } from './styles.native';

const ControlPane: React.FC = () => {
  const hideControlPanel = useConfigStore(state => state.hideControlPanel);
  if (hideControlPanel) {
    return null;
  }
  return (
    <View
      style={controlPaneStyles.controlPane}
      testID="cometchat-control-panel">
      <AudioControl />
      <VideoControl />
      <AudioModeButton />
      <MoreMenuButton />
      <LeaveSessionButton />
    </View>
  );
};

export default ControlPane;
