import {
  eventBus,
  INTERNAL_EVENTS,
  useTracksStore,
} from '@cometchat/calls-sdk-core';
import { permissions } from 'react-native-webrtc';

async function queryPermissions() {
  try {
    const [cameraPermission, microphonePermission] = await Promise.all([
      permissions.query({ name: 'microphone' as PermissionName }),
      permissions.query({ name: 'camera' as PermissionName }),
    ]);

    useTracksStore.setState(state => ({
      permissions: {
        ...state.permissions,
        video: cameraPermission === 'granted',
        audio: microphonePermission === 'granted',
        initialized: true,
      },
    }));
  } catch (error) {
    console.warn('Failed to query permissions:', error);
  }
}

eventBus.subscribe(INTERNAL_EVENTS.lifecycle.componentDidMount, () => {
  queryPermissions();
});

eventBus.subscribe(INTERNAL_EVENTS.queryPermission, () => {
  queryPermissions();
});
