import {
  getAvatarTextInitials,
  getColorFromName,
} from '@cometchat/calls-sdk-core';
import React, { useMemo } from 'react';
import {
  Image,
  StyleProp,
  StyleSheet,
  Text,
  TextStyle,
  View,
  ViewStyle,
} from 'react-native';
import { colors, commonStyles } from '../theme/style-variables';

interface AvatarProps {
  name: string;
  imageUrl?: string;
  size?: number;
  fontSize?: number;
  containerStyle?: StyleProp<ViewStyle>;
  textStyle?: StyleProp<TextStyle>;
}

const Avatar: React.FC<AvatarProps> = ({
  name,
  imageUrl,
  size,
  fontSize,
  containerStyle,
  textStyle,
}) => {
  const wrapperStyle = size
    ? { width: size, height: size }
    : styles.avatarWrapper;
  const fallbackTextStyle = fontSize
    ? { fontSize, lineHeight: fontSize * 1.2 }
    : {};

  const backgroundStyle = useMemo(() => {
    if (imageUrl) {
      return {};
    }
    return { backgroundColor: getColorFromName(name) };
  }, [imageUrl, name]);

  return (
    <View
      style={[
        styles.avatarWrapper,
        backgroundStyle,
        wrapperStyle,
        containerStyle,
      ]}>
      {imageUrl ? (
        <Image
          source={{ uri: imageUrl }}
          style={styles.avatarImage}
          resizeMode="cover"
        />
      ) : (
        <Text
          style={[
            commonStyles.heading2Bold,
            styles.avatarText,
            textStyle,
            fallbackTextStyle,
          ]}>
          {getAvatarTextInitials(name)}
        </Text>
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  avatarWrapper: {
    overflow: 'hidden',
    backgroundColor: '#3a3a3a',
    alignItems: 'center',
    justifyContent: 'center',
    width: 48,
    height: 48,
    borderRadius: 1000,
  },
  avatarImage: {
    width: '100%',
    height: '100%',
  },
  avatarText: {
    color: colors.text.primary,
  },
});

export default Avatar;
