import { useConferenceStore } from '@cometchat/calls-sdk-core';
import KeepAwakeModule from '../native-communication/KeepAwakeModule';

useConferenceStore.subscribe(
  state => state.conferenceStatus,
  conferenceStatus => {
    if (conferenceStatus === 'joined' || conferenceStatus === 'restored') {
      KeepAwakeModule.activateKeepAwake();
    } else {
      KeepAwakeModule.deactivateKeepAwake();
    }
  },
);
