import {
  MEDIA_TYPE,
  Participant,
  useIsParticipantPinned,
  useRaisedHandTimestamp,
  useTrackMuted,
} from '@cometchat/calls-sdk-core';
import React from 'react';
import { StyleProp, StyleSheet, Text, View, ViewStyle } from 'react-native';
import Icon from '../icon/Icon.native';
import { commonStyles } from '../theme/style-variables';

interface LabelProps {
  participant: Participant;
  style?: StyleProp<ViewStyle>;
}

const LabelIcon = ({
  type,
  muted,
  raisedHandTimestamp,
}: {
  type: Participant['type'];
  muted?: boolean;
  raisedHandTimestamp?: number;
}) => {
  if (type === 'screen-share') {
    return <Icon name="screen-share" size={16} fill="#858585" />;
  }
  if (raisedHandTimestamp) {
    return <Icon name="raise-hand-fill" size={16} fill="#141414" />;
  }
  if (muted) {
    return <Icon name="mic-off-fill" size={16} fill="#858585" />;
  }
  return <Icon name="wave" size={16} fill="#0B9F5D" />;
};

const Label = ({ participant, style }: LabelProps) => {
  const { name, isLocal, type, pid } = participant;
  const muted = useTrackMuted(MEDIA_TYPE.AUDIO, pid);
  const raisedHandTimestamp = useRaisedHandTimestamp(pid, type);
  const isParticipantPinned = useIsParticipantPinned(pid, type);

  return (
    <View
      style={[
        styles.userLabel,
        raisedHandTimestamp ? styles.userLabelRaisedHand : {},
        style,
      ]}>
      {isParticipantPinned && (
        <Icon
          name="pin"
          size={16}
          fill={raisedHandTimestamp ? '#141414' : '#FFF'}
        />
      )}
      <LabelIcon
        type={type}
        muted={muted}
        raisedHandTimestamp={raisedHandTimestamp}
      />
      <Text
        style={[
          commonStyles.caption1Regular,
          styles.userName,
          raisedHandTimestamp ? styles.userNameRaisedHand : {},
        ]}
        numberOfLines={1}
        ellipsizeMode="tail">
        {name} {isLocal && '(You)'}
      </Text>
    </View>
  );
};

const styles = StyleSheet.create({
  userLabel: {
    display: 'flex',
    flexDirection: 'row',
    justifyContent: 'flex-start',
    alignItems: 'center',
    padding: 4,
    position: 'absolute',
    left: 4,
    bottom: 4,
    backgroundColor: '#141414CC',
    borderRadius: 4,
    gap: 2,
    maxWidth: '95%',
  },
  userLabelRaisedHand: {
    backgroundColor: '#FFFFFF',
    borderRadius: 1000,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.2,
    shadowRadius: 10,
    elevation: 5,
  },
  userName: {
    color: '#ffffff',
    flexShrink: 1,
  },
  userNameRaisedHand: {
    color: '#141414',
  },
});

export default Label;
