import {
  MEDIA_TYPE,
  Participant,
  useEnableParticipantContextMenu,
  useShouldMirrorLocalVideo,
  useTrackByParticipantId,
  useTrackMuted,
} from '@cometchat/calls-sdk-core';
import React from 'react';
import {
  StyleProp,
  StyleSheet,
  TouchableOpacity,
  View,
  ViewStyle,
} from 'react-native';
import Avatar from '../avatar/Avatar.native';
import MoreOptionButton from '../participants/participant-item/MoreOptionButton';
import Label from '../shared/Label.native';
import Video from '../video/Video.native';

interface TileProps {
  participant: Participant;
  style?: StyleProp<ViewStyle>;
  zOrder?: number;
  showLabel?: boolean;
  disablePress?: boolean;
}

const Tile = ({
  participant,
  style,
  zOrder,
  showLabel = true,
  disablePress = false,
}: TileProps) => {
  const { name, avatar, type, pid, ruid, isLocal } = participant;
  const videoTrack = useTrackByParticipantId(
    pid,
    type === 'screen-share' ? MEDIA_TYPE.SCREENSHARE : MEDIA_TYPE.VIDEO,
  )?.originalTrack;
  const videoMuted = useTrackMuted(
    type === 'screen-share' ? MEDIA_TYPE.SCREENSHARE : MEDIA_TYPE.VIDEO,
    pid,
  );
  const enableParticipantContextMenu = useEnableParticipantContextMenu();
  const shouldMirror = useShouldMirrorLocalVideo();

  const [size, fontSize] = React.useMemo(() => {
    const flatStyle = StyleSheet.flatten(style);
    const width = flatStyle?.width;
    const height = flatStyle?.height;
    if (typeof width === 'number' && typeof height === 'number') {
      const calculatedSize = Math.min(Math.min(width, height) >> 1, 120);
      return [calculatedSize, calculatedSize >> 1];
    }
    return [48, 24];
  }, [style]);

  return (
    <TouchableOpacity
      activeOpacity={1}
      disabled={disablePress}
      style={[styles.callScreen, style]}
      testID={`cometchat-tile-${pid}`}>
      <View style={styles.tileAvatar}>
        <Avatar name={name} imageUrl={avatar} size={size} fontSize={fontSize} />
      </View>
      <Video
        videoTrack={videoTrack}
        objectFit={type === 'screen-share' ? 'contain' : 'cover'}
        muted={videoMuted}
        zOrder={zOrder}
        mirror={isLocal && type !== 'screen-share' && shouldMirror}
      />
      {showLabel && <Label participant={participant} />}
      {enableParticipantContextMenu && (
        <View style={styles.rightTopButton}>
          <MoreOptionButton ruid={ruid} />
        </View>
      )}
    </TouchableOpacity>
  );
};

const styles = StyleSheet.create({
  callScreen: {
    width: '100%',
    height: '100%',
    backgroundColor: '#272727',
    position: 'relative',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: 8,
    overflow: 'hidden',
  },
  tileAvatar: {
    width: '100%',
    height: '100%',
    alignItems: 'center',
    justifyContent: 'center',
    flexShrink: 0,
  },
  rightTopButton: {
    position: 'absolute',
    top: 4,
    right: 4,
  },
});

export default Tile;
