import {
  startScreenSharing,
  stopScreenSharing,
  useScreenShareRunning,
} from '@cometchat/calls-sdk-core';
import React from 'react';
import MenuItem from './MenuItem.native';

const ScreenShareButton = () => {
  const isScreenShareRunning = useScreenShareRunning();

  return (
    <MenuItem
      iconName={isScreenShareRunning ? 'screen-share-stop' : 'screen-share'}
      selected={isScreenShareRunning}
      label={
        isScreenShareRunning ? 'Stop screen sharing' : 'Start Screen Sharing'
      }
      onPress={isScreenShareRunning ? stopScreenSharing : startScreenSharing}
    />
  );
};

export default ScreenShareButton;
