import {
  EVENT_LISTENER_METHODS,
  eventBus,
  LAYOUT,
  useBaseStore,
  useConfigStore,
  useLayout,
} from '@cometchat/calls-sdk-core';
import React, { useRef, useState } from 'react';
import { TouchableOpacity, View } from 'react-native';
import Icon from '../icon/Icon.native';
import { PopupMenu } from '../shared/Popup';
import { styles } from './styles';

const ChangeLayout: React.FC = () => {
  const hideChangeLayoutButton = useConfigStore(
    state => state.hideChangeLayoutButton,
  );
  const [menuVisible, setMenuVisible] = useState(false);
  const layout = useLayout();
  const buttonRef = useRef<View>(null);
  const [anchorLayout, setAnchorLayout] = useState({
    x: 0,
    y: 0,
    width: 0,
    height: 0,
  });

  if (hideChangeLayoutButton) {
    return null;
  }

  const showMenu = () => {
    if (buttonRef.current) {
      buttonRef.current.measureInWindow((x, y, width, height) => {
        setAnchorLayout({ x, y, width, height });
        setMenuVisible(true);
      });
    }
  };
  return (
    <>
      <TouchableOpacity
        ref={buttonRef}
        style={[styles.iconButton]}
        onPress={() => {
          eventBus.publish({
            type: EVENT_LISTENER_METHODS.ButtonClickListener
              .onChangeLayoutButtonClicked,
          });
          showMenu();
        }}
        testID="cometchat-change-layout-button">
        <Icon name="tile-fill" fill={'#FFFFFF'} />
      </TouchableOpacity>
      <PopupMenu
        visible={menuVisible}
        anchorLayout={anchorLayout}
        onClose={() => setMenuVisible(false)}
        options={[
          {
            label: 'Tile View',
            iconName: 'tile-fill',
            selected: layout === LAYOUT.TILE,
            onPress: () => {
              useBaseStore.setState({ layout: LAYOUT.TILE });
            },
          },
          {
            label: 'Sidebar View',
            iconName: 'sidebar',
            selected: layout === LAYOUT.SIDEBAR,
            onPress: () => {
              useBaseStore.setState({ layout: LAYOUT.SIDEBAR });
            },
          },
          {
            label: 'Spotlight View',
            iconName: 'spotlight',
            selected: layout === LAYOUT.SPOTLIGHT,
            onPress: () => {
              useBaseStore.setState({ layout: LAYOUT.SPOTLIGHT });
            },
          },
        ]}
      />
    </>
  );
};

export default ChangeLayout;
