import { Participant, useConferenceStore } from '@cometchat/calls-sdk-core';
import React from 'react';
import Icon from '../../icon/Icon.native';

const QUALITY_COLOR_MAP: Record<number, string> = {
  1: '#C73C3E',
  2: '#D08D04',
  3: '#0B9F5D',
  4: '#0B9F5D',
};

const ConnectionQualityIndicator = ({
  participantId,
}: {
  participantId: Participant['pid'];
}) => {
  const connectionQuality = useConferenceStore(state =>
    state.connectionQuality.get(participantId),
  );
  if (connectionQuality === undefined) {
    return null;
  }
  const quality = (connectionQuality >> 5) + 1;
  const signalColor = QUALITY_COLOR_MAP[quality];
  return <Icon name="signal" size={24} fill={signalColor} />;
};

export default ConnectionQualityIndicator;
