import React, { useEffect, useRef, useState } from 'react';
import { Animated, StyleProp, StyleSheet, ViewStyle } from 'react-native';
import { RTCView } from 'react-native-webrtc';
import { commonStyles } from '../theme/style-variables';

interface VideoNativeProps {
  videoTrack: any;
  style?: StyleProp<ViewStyle>;
  objectFit?: 'cover' | 'contain';
  mirror?: boolean;
  muted?: boolean;
  zOrder?: number;
}

const VideoNative: React.FC<VideoNativeProps> = ({
  videoTrack,
  style,
  objectFit = 'cover',
  mirror = false,
  muted = false,
  zOrder = 0,
}) => {
  const [streamURL, setStreamURL] = useState<any | null>(null);
  const fadeAnim = useRef(new Animated.Value(muted ? 0 : 1)).current;

  useEffect(() => {
    if (videoTrack) {
      setStreamURL(videoTrack.getOriginalStream());
    }
  }, [videoTrack]);

  useEffect(() => {
    Animated.timing(fadeAnim, {
      toValue: muted ? 0 : 1,
      duration: 300,
      useNativeDriver: true,
    }).start();
  }, [muted, fadeAnim]);

  if (!streamURL) {
    return null;
  }

  return (
    <Animated.View
      style={[
        commonStyles.absoluteFill,
        styles.videoContainer,
        { opacity: fadeAnim },
      ]}>
      <RTCView
        streamURL={streamURL.toURL()}
        style={[styles.video, style]}
        objectFit={objectFit}
        mirror={mirror}
        zOrder={zOrder}
      />
    </Animated.View>
  );
};

const styles = StyleSheet.create({
  videoContainer: {
    height: '100%',
    width: '100%',
  },
  video: {
    width: '100%',
    height: '100%',
  },
});

export default VideoNative;
