import {
  MEDIA_TYPE,
  muteParticipant,
  pinParticipant,
  unpinParticipant,
  useAllParticipants,
  useIsParticipantPinned,
  useLocalParticipant,
  useTrackMuted,
} from '@cometchat/calls-sdk-core';
import React, { useMemo, useRef, useState } from 'react';
import { TouchableOpacity, View } from 'react-native';
import { IconName } from '../../icon/icon-paths-24x24';
import Icon from '../../icon/Icon.native';
import { PopupMenu } from '../../shared/Popup';
import { styles } from './styles';

interface MoreOptionButtonProps {
  ruid: string;
}

const MoreOptionButton: React.FC<MoreOptionButtonProps> = ({ ruid }) => {
  const [menuVisible, setMenuVisible] = useState(false);
  const buttonRef = useRef<View>(null);
  const [anchorLayout, setAnchorLayout] = useState({
    x: 0,
    y: 0,
    width: 0,
    height: 0,
  });
  const participant = useAllParticipants().find(p => p.ruid === ruid)!;
  const localParticipant = useLocalParticipant();
  const isParticipantPinned = useIsParticipantPinned(
    participant?.pid,
    participant?.type,
  );
  const muted = useTrackMuted(MEDIA_TYPE.AUDIO, participant?.pid);

  const options = useMemo(() => {
    const opts: { label: string; onPress: () => void; iconName?: IconName }[] =
      [
        {
          label: isParticipantPinned ? 'Unpin' : 'Pin',
          iconName: isParticipantPinned ? 'unpin' : 'pin',
          onPress: () => {
            if (isParticipantPinned) {
              unpinParticipant();
            } else {
              pinParticipant(participant.pid, participant.type);
            }
          },
        },
      ];
    if (!participant) {
      return opts;
    }

    if (
      localParticipant.role === 'moderator' &&
      participant.pid !== localParticipant.pid
    ) {
      if (!muted) {
        opts.push({
          label: 'Mute Audio',
          iconName: 'mic-off',
          onPress: () => {
            muteParticipant(participant.pid);
          },
        });
      }
    }
    return opts;
  }, [
    isParticipantPinned,
    participant,
    localParticipant.role,
    localParticipant.pid,
    muted,
  ]);

  if (!participant) {
    return null;
  }

  const showMenu = () => {
    if (buttonRef.current) {
      buttonRef.current.measureInWindow((x, y, width, height) => {
        setAnchorLayout({ x, y, width, height });
        setMenuVisible(true);
      });
    }
  };

  return (
    <>
      <TouchableOpacity
        ref={buttonRef}
        style={styles.moreButton}
        onPress={showMenu}
        testID="cometchat-participant-more-options-button">
        <Icon name="more" size={20} fill="#767676" />
      </TouchableOpacity>
      <PopupMenu
        visible={menuVisible}
        anchorLayout={anchorLayout}
        onClose={() => setMenuVisible(false)}
        options={options}
      />
    </>
  );
};

export default MoreOptionButton;
