import {
  leaveSession,
  leaveSessionDueToIdleTimeout,
  miliSecondsToMMSS,
  useBaseStore,
  useConfigStore,
} from '@cometchat/calls-sdk-core';
import React, { useEffect, useRef, useState } from 'react';
import {
  Animated,
  Modal,
  StyleSheet,
  Text,
  TouchableOpacity,
  TouchableWithoutFeedback,
  View,
} from 'react-native';
import { commonStyles } from '../theme/style-variables';

export interface IdealTimeoutModalProps {
  style?: any;
}

const IdealTimeoutModal: React.FC<IdealTimeoutModalProps> = ({
  style = {},
}) => {
  const idleTimeoutModalVisible = useBaseStore(
    state => state.idleTimeoutModalVisible,
  );
  const idleTimeoutPeriodAfterPrompt = useConfigStore(
    state => state.idleTimeoutPeriodAfterPrompt,
  );
  const [ms, setMs] = useState(idleTimeoutPeriodAfterPrompt);
  const formattedTime = miliSecondsToMMSS(ms);
  const fadeAnim = useRef(new Animated.Value(0)).current;
  const scaleAnim = useRef(new Animated.Value(0.8)).current;

  const ceilMinutes = Math.ceil(ms / 60000);

  const onStayInCall = () => {
    useBaseStore.getState().restartIdealTimeoutTimer();
  };

  const handleOverlayPress = () => {
    onStayInCall();
  };

  useEffect(() => {
    if (idleTimeoutModalVisible) {
      Animated.parallel([
        Animated.timing(fadeAnim, {
          toValue: 1,
          duration: 300,
          useNativeDriver: true,
        }),
        Animated.spring(scaleAnim, {
          toValue: 1,
          tension: 100,
          friction: 8,
          useNativeDriver: true,
        }),
      ]).start();
    } else {
      Animated.parallel([
        Animated.timing(fadeAnim, {
          toValue: 0,
          duration: 200,
          useNativeDriver: true,
        }),
        Animated.timing(scaleAnim, {
          toValue: 0.8,
          duration: 200,
          useNativeDriver: true,
        }),
      ]).start();
    }
  }, [idleTimeoutModalVisible, fadeAnim, scaleAnim]);

  useEffect(() => {
    const timer = setInterval(() => {
      if (!idleTimeoutModalVisible) {
        clearInterval(timer);
        return;
      }
      setMs(prev => {
        if (prev <= 1000) {
          clearInterval(timer);
          leaveSessionDueToIdleTimeout();
          return 0;
        }
        return prev - 1000;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [idleTimeoutModalVisible]);

  useEffect(() => {
    if (idleTimeoutModalVisible) {
      setMs(idleTimeoutPeriodAfterPrompt);
    }
  }, [idleTimeoutModalVisible, idleTimeoutPeriodAfterPrompt]);

  if (!idleTimeoutModalVisible) {
    return null;
  }

  return (
    <Modal
      transparent
      visible={idleTimeoutModalVisible}
      animationType="none"
      supportedOrientations={['portrait', 'landscape-left', 'landscape-right']}
      statusBarTranslucent>
      <TouchableWithoutFeedback
        onPress={handleOverlayPress}
        testID="cometchat-idle-timeout-overlay">
        <Animated.View style={[styles.overlay, { opacity: fadeAnim }]}>
          <TouchableWithoutFeedback testID="cometchat-idle-timeout-modal">
            <Animated.View
              style={[
                styles.modal,
                style,
                {
                  opacity: fadeAnim,
                  transform: [{ scale: scaleAnim }],
                },
              ]}>
              <View style={styles.content}>
                {/* Timer Icon */}
                <View style={styles.timerIcon}>
                  <Text style={[commonStyles.heading3Bold, styles.timerText]}>
                    {formattedTime}
                  </Text>
                </View>

                {/* Text Content */}
                <View style={styles.textContent}>
                  <Text style={[commonStyles.heading2Medium, styles.title]}>
                    Are you still there?
                  </Text>
                  <Text style={[commonStyles.bodyRegular, styles.subtitle]}>
                    You are the only one here, so this call will end in less
                    than {ceilMinutes} minute{ceilMinutes > 1 ? 's' : ''}. Do
                    you want to stay in this call?
                  </Text>
                </View>

                {/* Action Buttons */}
                <View style={styles.actions}>
                  <TouchableOpacity
                    style={[styles.button, styles.buttonSecondary]}
                    onPress={onStayInCall}
                    activeOpacity={0.8}
                    testID="cometchat-idle-timeout-stay-button">
                    <Text
                      style={[
                        commonStyles.bodyMedium,
                        styles.buttonSecondaryText,
                      ]}>
                      Stay on the call
                    </Text>
                  </TouchableOpacity>
                  <TouchableOpacity
                    style={[styles.button, styles.buttonPrimary]}
                    onPress={() => leaveSession()}
                    activeOpacity={0.8}
                    testID="cometchat-idle-timeout-leave-button">
                    <Text
                      style={[
                        commonStyles.bodyMedium,
                        styles.buttonPrimaryText,
                      ]}>
                      Leave now
                    </Text>
                  </TouchableOpacity>
                </View>
              </View>
            </Animated.View>
          </TouchableWithoutFeedback>
        </Animated.View>
      </TouchableWithoutFeedback>
    </Modal>
  );
};

const styles = StyleSheet.create({
  overlay: {
    flex: 1,
    backgroundColor: 'rgba(0, 0, 0, 0.6)',
    justifyContent: 'center',
    alignItems: 'center',
    paddingHorizontal: 20,
  },
  modal: {
    backgroundColor: '#141414',
    borderRadius: 20,
    borderWidth: 1,
    borderColor: '#383838',
    width: '100%',
    maxWidth: 372,
    paddingTop: 32,
    paddingHorizontal: 20,
    paddingBottom: 20,
    shadowColor: '#000',
    shadowOffset: {
      width: 0,
      height: 12,
    },
    shadowOpacity: 0.08,
    shadowRadius: 16,
    elevation: 8,
  },
  content: {
    alignItems: 'center',
    gap: 20,
  },
  timerIcon: {
    width: 80,
    height: 80,
    borderRadius: 40,
    backgroundColor: '#473892',
    justifyContent: 'center',
    alignItems: 'center',
  },
  timerText: {
    color: '#FFFFFF',
    textAlign: 'center',
  },
  textContent: {
    alignItems: 'center',
    gap: 8,
    width: '100%',
  },
  title: {
    color: '#FFFFFF',
    textAlign: 'center',
    width: '100%',
  },
  subtitle: {
    color: '#B8B8B8',
    textAlign: 'center',
    lineHeight: 20,
    width: '100%',
  },
  actions: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 12,
  },
  button: {
    flex: 1,
    height: 40,
    justifyContent: 'center',
    alignItems: 'center',
    borderRadius: 8,
  },
  buttonSecondary: {
    backgroundColor: 'transparent',
    borderWidth: 1,
    borderColor: '#383838',
  },
  buttonSecondaryText: {
    color: '#FFFFFF',
  },
  buttonPrimary: {
    backgroundColor: '#C73C3E',
  },
  buttonPrimaryText: {
    color: '#FFFFFF',
  },
});

export default IdealTimeoutModal;
