import {
  LAYOUT,
  useBaseStore,
  useIsReconnecting,
  useLayout,
} from '@cometchat/calls-sdk-core';
import React from 'react';
import { StyleSheet, View } from 'react-native';
import SidebarLayout from './layout/SidebarLayout.native';
import { Spotlight } from './layout/Spotlight.native';
import TileLayout from './layout/TileLayout';
import { ProcessingOverlay } from './processing-overlay/ProcessingOverlay.native';
import RecordingIndicator from './recording-indicator/RecordingIndicator.native';

function CallStage() {
  const mainArea = useBaseStore(state => state.mainAreaDimension);
  const layout = useLayout();
  const isReconnecting = useIsReconnecting();

  const mainAreaAvailable = mainArea.width > 0 && mainArea.height > 0;

  return (
    <View
      style={styles.container}
      onLayout={e => {
        useBaseStore.setState({
          mainAreaDimension: {
            width: e.nativeEvent.layout.width,
            height: e.nativeEvent.layout.height,
          },
        });
      }}>
      {layout === LAYOUT.TILE && mainAreaAvailable && <TileLayout />}
      {layout === LAYOUT.SPOTLIGHT && mainAreaAvailable && <Spotlight />}
      {layout === LAYOUT.SIDEBAR && mainAreaAvailable && <SidebarLayout />}
      <RecordingIndicator />
      {isReconnecting && (
        <ProcessingOverlay message="You've been disconnected. Attempting to reconnect…" />
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    marginHorizontal: 20,
    marginVertical: 8,
  },
});

export default CallStage;
